// Normaliza texto de cargo/função pra comparação tolerante: remove acentos, pontuação
// (inclui "." de abreviações como "AUX.") e hífen/underline, colapsa espaços. Usada tanto
// pra achar o cargo do catálogo na Ordem de Serviço quanto pra avisar quando não achar.
function normalizarTextoCargo(s) {
    return String(s || '')
        .normalize('NFD').replace(/[̀-ͯ]/g, '')
        .toLowerCase()
        .replace(/[.\-_/,;:()]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
}

// Acha o cargo do catálogo do GHE que corresponde à função cadastrada do colaborador.
// 1) Igualdade exata após normalizar (mesmo comportamento de antes, só que tolerante a
// acento/pontuação/hífen). 2) Se não achar, tenta "contém" nos dois sentidos - cobre
// abreviação ("AUX." vs "Auxiliar") e sufixo de turno ("VIGIA - DIURNO" vs "Vigia"). Se
// mais de um cargo do grupo bater no "contém", NÃO escolhe nenhum - devolve ambiguo:true
// pra quem chama tratar como "sem correspondência" em vez de arriscar mostrar o
// EPI/atividade de um cargo errado num documento de segurança (ver textoAvisoCargoOs).
function resolverCargoInfoDoColaborador(ghe, funcaoColaborador) {
    if (!ghe || !Array.isArray(ghe.cargos) || ghe.cargos.length === 0) return { cargoInfo: null, ambiguo: false };
    const funcaoNorm = normalizarTextoCargo(funcaoColaborador);
    if (!funcaoNorm) return { cargoInfo: null, ambiguo: false };

    const exato = ghe.cargos.find(c => normalizarTextoCargo(c.funcao) === funcaoNorm);
    if (exato) return { cargoInfo: exato, ambiguo: false };

    const candidatos = ghe.cargos.filter(c => {
        const cargoNorm = normalizarTextoCargo(c.funcao);
        return cargoNorm && (funcaoNorm.includes(cargoNorm) || cargoNorm.includes(funcaoNorm));
    });
    if (candidatos.length === 1) return { cargoInfo: candidatos[0], ambiguo: false };
    if (candidatos.length > 1) return { cargoInfo: null, ambiguo: true };
    return { cargoInfo: null, ambiguo: false };
}

// Mesma resolução acima, mas já resolve o GHE do colaborador junto - usada tanto pela
// Ordem de Serviço quanto pelo indicador ⚠️ no botão "🖨️ OS" da lista, pra avisar ANTES
// de gerar o documento em branco silenciosamente.
function avaliarCorrespondenciaCargoOs(matricula, funcaoFallback) {
    const colab = allEfetivo.find(e => e.id === matricula);
    const ghe = colab?.ghe ? allGheCatalogo.find(g => g.id === normalizarGhe(colab.ghe)) : null;
    const funcao = colab?.funcao || funcaoFallback || '';
    const { cargoInfo, ambiguo } = resolverCargoInfoDoColaborador(ghe, funcao);
    return { colab, ghe, funcao, cargoInfo, ambiguo, semCorrespondencia: !ghe || !cargoInfo };
}

// Texto de aviso impresso no topo da própria Ordem de Serviço quando não foi possível
// resolver o cargo do catálogo pra função cadastrada - fica visível no documento em vez
// de só sair em branco, pra o usuário perceber e corrigir o cadastro antes de entregar
// pro colaborador.
function textoAvisoCargoOs({ ghe, funcao, ambiguo }) {
    if (!ghe) {
        return `⚠️ Não foi possível identificar o GHE deste colaborador (campo "GHE" vazio ou não encontrado no catálogo) - Setor, Cargo e as demais seções desta Ordem de Serviço não puderam ser preenchidas automaticamente.`;
    }
    if (ambiguo) {
        return `⚠️ A função cadastrada ("${funcao}") corresponde a mais de um cargo do catálogo do GHE ${ghe.id} - por segurança, nenhum foi escolhido automaticamente. Revise em Gerenciar GHE > GRUPO ${ghe.id} e ajuste a função no cadastro do colaborador (ou os cargos do catálogo) pra eliminar a ambiguidade.`;
    }
    return `⚠️ Não foi encontrada correspondência entre a função cadastrada ("${funcao}") e os cargos do catálogo do GHE ${ghe.id}. Revise em Gerenciar GHE > GRUPO ${ghe.id} e associe o cargo correto.`;
}

// Ordem de Serviço de Segurança e Saúde no Trabalho (NR-01, item 1.4.1.1 "e") -
// documento individual obrigatório informando riscos da função e EPI/EPC exigidos,
// exigido pela empresa atual do usuário e ausente no sistema até aqui. Junta-se ao Kit
// de Integração (mesmo momento de admissão) em vez de virar um botão à parte, por
// pedido explícito do usuário. Fonte de setor/cargo/agentes/EPI: colaboradores_efetivo
// (ghe) → ghe_catalogo (cargos[].descricao_atividade/agentes/epis_necessarios/
// epcs_necessarios) - campos que ainda não tiverem sido preenchidos pelo usuário para
// aquele cargo aparecem em branco, nunca com um valor fabricado.
function construirFolhaOrdemServico(matricula, r, campos, data) {
    const colab = allEfetivo.find(e => e.id === matricula);
    const ghe = colab?.ghe ? allGheCatalogo.find(g => g.id === normalizarGhe(colab.ghe)) : null;
    const { cargoInfo, ambiguo } = resolverCargoInfoDoColaborador(ghe, r.funcao);
    const avisoCargo = !cargoInfo ? textoAvisoCargoOs({ ghe, funcao: r.funcao, ambiguo }) : null;
    const ag = cargoInfo?.agentes || {};
    const epis = Array.isArray(cargoInfo?.epis_necessarios) ? cargoInfo.epis_necessarios : [];
    const epcs = Array.isArray(cargoInfo?.epcs_necessarios) ? cargoInfo.epcs_necessarios : [];
    const codigoOs = codigoRevisaoDocumento('ordem_servico');
    // Texto único da empresa (não varia por cargo) - reaproveita o campo Observações já
    // existente no cadastro de Documentos (Documentos > Ordem de Serviço > Observações),
    // em vez de criar uma tela nova só pra esse texto.
    const responsabilidadesEmpregado = allDocumentosControle.find(d => d.id === 'ordem_servico')?.observacoes || '';

    return `<div class="folha folha-compacta">
        <div class="titulo" style="font-size:16px;">ORDEM DE SERVIÇO DE SEGURANÇA E SAÚDE NO TRABALHO</div>
        ${codigoOs ? `<div class="subtitulo">${escapeHTML(codigoOs)}</div>` : ''}
        ${avisoCargo ? `<div style="background:#fff3cd; border:1px solid #f0ad4e; color:#7a5b00; border-radius:6px; padding:8px 10px; font-size:11px; font-weight:600; margin-bottom:10px;">${escapeHTML(avisoCargo)}</div>` : ''}
        <table style="width:100%; border-collapse:collapse; font-size:11px; margin-bottom:10px;">
            <tr><td style="border:1px solid #ccc; padding:4px 6px;"><b>Emissão:</b> ${formatSimpleDate(data)}</td>
                <td style="border:1px solid #ccc; padding:4px 6px;"><b>Empresa:</b> ${escapeHTML(EMPRESA_INFO.razaoSocial)}</td>
                <td style="border:1px solid #ccc; padding:4px 6px;"><b>CNPJ:</b> ${escapeHTML(EMPRESA_INFO.cnpj)}</td></tr>
            <tr><td style="border:1px solid #ccc; padding:4px 6px;" colspan="2"><b>Funcionário:</b> ${escapeHTML(r.nome)}</td>
                <td style="border:1px solid #ccc; padding:4px 6px;"><b>CPF:</b> ${escapeHTML(colab?.cpf || '')}</td></tr>
            <tr><td style="border:1px solid #ccc; padding:4px 6px;"><b>Setor:</b> ${escapeHTML(ghe ? `${ghe.id} - ${ghe.nome}` : '')}</td>
                <td style="border:1px solid #ccc; padding:4px 6px;"><b>Cargo:</b> ${escapeHTML(cargoInfo?.cargo || '')}</td>
                <td style="border:1px solid #ccc; padding:4px 6px;"><b>Função:</b> ${escapeHTML(r.funcao || '')}</td></tr>
        </table>

        <div class="bloco-titulo">1. Descrição das Atividades:</div>
        <div class="texto">${escapeHTML(cargoInfo?.descricao_atividade || '')}</div>

        <div class="bloco"><div class="bloco-titulo">2. Agentes associados às atividades:</div>
            <table style="width:100%; border-collapse:collapse; font-size:11px;">
                <thead><tr style="background:#f2f2f2;">
                    <th style="border:1px solid #ccc; padding:4px 6px;">Físico</th><th style="border:1px solid #ccc; padding:4px 6px;">Químico</th>
                    <th style="border:1px solid #ccc; padding:4px 6px;">Biológico</th><th style="border:1px solid #ccc; padding:4px 6px;">Ergonômico</th>
                    <th style="border:1px solid #ccc; padding:4px 6px;">Acidentes</th>
                </tr></thead>
                <tbody><tr>
                    <td style="border:1px solid #ccc; padding:4px 6px;">${escapeHTML(ag.fisico || '')}</td>
                    <td style="border:1px solid #ccc; padding:4px 6px;">${escapeHTML(ag.quimico || '')}</td>
                    <td style="border:1px solid #ccc; padding:4px 6px;">${escapeHTML(ag.biologico || '')}</td>
                    <td style="border:1px solid #ccc; padding:4px 6px;">${escapeHTML(ag.ergonomico || '')}</td>
                    <td style="border:1px solid #ccc; padding:4px 6px;">${escapeHTML(ag.acidentes || '')}</td>
                </tr></tbody>
            </table>
        </div>

        <div class="bloco"><div class="bloco-titulo">3. EPIs Necessários para a Função:</div>
            <div class="lista-itens">${epis.length ? epis.map(e => `<div>» ${escapeHTML(e)}</div>`).join('') : '<div style="color:#888;">—</div>'}</div>
        </div>
        <div class="bloco"><div class="bloco-titulo">4. EPCs Necessários para a Função:</div>
            <div class="lista-itens">${epcs.length ? epcs.map(e => `<div>» ${escapeHTML(e)}</div>`).join('') : '<div style="color:#888;">—</div>'}</div>
        </div>
        <div class="bloco"><div class="bloco-titulo">5. Recomendações:</div><div class="texto">${escapeHTML(cargoInfo?.recomendacoes || '')}</div></div>
        <div class="bloco"><div class="bloco-titulo">6. Procedimentos em caso de acidentes:</div><div class="texto">${escapeHTML(cargoInfo?.procedimentos_acidentes || '')}</div></div>
        <div class="bloco"><div class="bloco-titulo">7. Responsabilidades do Empregado (NR-01 do Ministério do Trabalho e Previdência):</div><div class="texto">${escapeHTML(responsabilidadesEmpregado)}</div></div>
        <div class="bloco"><div class="bloco-titulo">8. Observações:</div><div class="texto">${escapeHTML(cargoInfo?.observacoes || '')}</div></div>

        <div class="texto" style="margin-top:16px;">
            Declaro que recebi da <b>${escapeHTML(EMPRESA_INFO.razaoSocial)}</b> as orientações que fazem parte deste documento, bem como cópia
            do mesmo, comprometendo-me a seguir as orientações nele contidas e reconhecendo serem elas indispensáveis à minha segurança e à
            de meus colegas de trabalho. Também afirmo ter recebido os EPIs de utilização obrigatória na minha função e comprometo-me a
            utilizá-los durante toda a minha jornada de trabalho, solicitando sua substituição sempre que necessário.
        </div>
        <div class="assinaturas">
            ${blocoAssinatura(`${escapeHTML(r.nome)}<br>Colaborador`)}
            ${blocoAssinatura(`${escapeHTML(campos.responsavel_tecnico_nome || '')}<br>${escapeHTML(campos.responsavel_tecnico_qualificacao || '')}${campos.responsavel_tecnico_registro ? '<br>' + escapeHTML(campos.responsavel_tecnico_registro) : ''}`)}
        </div>
    </div>`;
}

function abrirDocumentoBlob(html) {
    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.target = '_blank';
    a.rel = 'noopener';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 30000);
}

// ============================================
// GESTÃO DE EQUIPES - corrige o campo "responsavel" de colaboradores_efetivo em lote
// quando alguém muda de equipe. Sem isso, a única forma de corrigir era editar um
// colaborador de cada vez pelo formulário completo de Efetivo (todos os campos, não só
// o responsável) - motivo real: usuário reportou que "Carregar equipe do Responsável"
// (em Lançar Treinamento) às vezes não traz um colaborador porque o campo responsavel
// dele ainda aponta pro encarregado antigo.
// ============================================

function popularEquipesResponsavelDatalist() {
    const dl = document.getElementById('equipesResponsavelList');
    if (!dl) return;
    dl.innerHTML = '';
    const responsaveis = new Set();
    allEfetivo.forEach(e => { if (colaboradorEstaAtivo(e) && e.responsavel) responsaveis.add(e.responsavel); });
    Array.from(responsaveis).sort().forEach(r => {
        const opt = document.createElement('option');
        opt.value = r;
        dl.appendChild(opt);
    });
}

function limparBuscaEquipes() {
    document.getElementById('equipesResponsavelInput').value = '';
    renderEquipeAtual();
}

function renderEquipeAtual() {
    const responsavel = document.getElementById('equipesResponsavelInput').value.trim();
    const container = document.getElementById('equipesConteudo');
    if (!responsavel) {
        container.innerHTML = '<div class="db-list-empty">Digite ou selecione um encarregado - se o nome já existir, abre a equipe dele; se for novo, cria uma equipe nova assim que você adicionar o primeiro colaborador abaixo.</div>';
        return;
    }

    const equipe = allEfetivo.filter(e => colaboradorEstaAtivo(e) && e.responsavel === responsavel)
        .sort((a, b) => (a.nome || '').localeCompare(b.nome || ''));
    const equipeExiste = equipe.length > 0;

    container.innerHTML = `
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; margin-bottom:8px; flex-wrap:wrap;">
            <span style="font-size:12px; color:var(--text-light); font-weight:600;">${equipeExiste ? `Equipe atual de ${escapeHTML(responsavel)}` : `Nova equipe: ${escapeHTML(responsavel)}`}</span>
            <div style="display:flex; align-items:center; gap:8px;">
                <span style="font-size:12px; color:var(--text-light);">${equipe.length} colaborador(es)</span>
                ${equipeExiste ? `<button class="db-clear-btn" style="padding:4px 10px; font-size:11.5px;" onclick="toggleRenomearEquipe()">✏️ Renomear Equipe</button>` : ''}
            </div>
        </div>
        <div id="equipesRenomearWrap" style="display:none; gap:8px; margin-bottom:12px; align-items:center;">
            <input type="text" id="equipesNovoNomeInput" placeholder="Novo nome do encarregado/equipe..." value="${escapeHTML(responsavel)}"
                   style="flex:1; padding:8px 10px; border:1px solid var(--border); border-radius:8px; font-size:12.5px; box-sizing:border-box;">
            <button class="db-apply-btn" style="padding:6px 12px; font-size:12px;" onclick="renomearEquipeAtual()">Salvar</button>
            <button class="db-clear-btn" style="padding:6px 12px; font-size:12px;" onclick="toggleRenomearEquipe()">Cancelar</button>
        </div>
        <div id="equipesListaAtual" class="db-list" style="max-height:280px; margin-bottom:16px;"></div>

        <label style="display:block; margin-bottom:4px; color:var(--text-light); font-weight:600; font-size:12.5px;">Adicionar colaborador a esta equipe</label>
        <input type="text" id="equipesAddColabInput" placeholder="Buscar por nome ou matrícula..."
               oninput="filterEquipesAddColab(this.value)" autocomplete="off"
               style="width:100%; padding:10px 12px; border:1px solid var(--border); border-radius:8px; font-size:13px; box-sizing:border-box; background:var(--card); color:var(--text); margin-bottom:8px;">
        <div id="equipesAddColabResults" class="db-list" style="max-height:220px;"></div>
        <span id="equipesStatus" style="font-size:12px; color:var(--text-light);"></span>
    `;

    const listaEl = document.getElementById('equipesListaAtual');
    if (equipe.length === 0) {
        listaEl.innerHTML = '<div class="db-list-empty">Ainda sem colaboradores - adicione o primeiro abaixo pra criar esta equipe.</div>';
    } else {
        listaEl.innerHTML = equipe.map(e => `
            <div class="db-list-item" style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
                <div>
                    <div class="db-list-item-title">${escapeHTML(e.nome || '')}</div>
                    <div class="db-list-item-sub">${escapeHTML(e.funcao || '')} — Matrícula ${escapeHTML(e.id)}</div>
                </div>
                <div style="display:flex; gap:6px; flex-shrink:0;">
                    <button class="db-clear-btn" onclick="editarColaboradorDaEquipe('${escapeHTML(e.id)}')">✏️ Editar</button>
                    <button class="db-clear-btn" style="color:var(--danger); border-color:var(--danger);" onclick="removerDaEquipe('${escapeHTML(e.id)}')">Remover</button>
                </div>
            </div>`).join('');
    }
}

function toggleRenomearEquipe() {
    const wrap = document.getElementById('equipesRenomearWrap');
    if (!wrap) return;
    const abrindo = wrap.style.display === 'none';
    wrap.style.display = abrindo ? 'flex' : 'none';
    if (abrindo) document.getElementById('equipesNovoNomeInput')?.focus();
}

// Renomeia a equipe inteira de uma vez - atualiza o campo `responsavel` de todos os
// colaboradores atualmente na equipe pro novo nome, num upsert só. Sem isso, corrigir o
// nome de um encarregado (ex: erro de digitação) exigia mover cada colaborador um por
// um pra uma "equipe nova" com o nome certo.
async function renomearEquipeAtual() {
    const nomeAtual = document.getElementById('equipesResponsavelInput').value.trim();
    const novoNome = document.getElementById('equipesNovoNomeInput').value.trim();
    const statusEl = document.getElementById('equipesStatus');
    if (!novoNome || novoNome === nomeAtual) { toggleRenomearEquipe(); return; }

    const equipe = allEfetivo.filter(e => colaboradorEstaAtivo(e) && e.responsavel === nomeAtual);
    if (equipe.length === 0) return;

    if (statusEl) { statusEl.textContent = `Renomeando ${equipe.length} colaborador(es)...`; statusEl.style.color = 'var(--text-light)'; }
    try {
        await supabaseUpsert('colaboradores_efetivo', equipe.map(e => ({ id: e.id, responsavel: novoNome })));
        equipe.forEach(e => { e.responsavel = novoNome; });
        document.getElementById('equipesResponsavelInput').value = novoNome;
        popularEquipesResponsavelDatalist();
        renderEquipeAtual();
        document.getElementById('equipesStatus').textContent = '✅ Equipe renomeada.';
        document.getElementById('equipesStatus').style.color = 'var(--success)';
    } catch (err) {
        console.error('Erro ao renomear equipe:', err);
        if (statusEl) { statusEl.textContent = '❌ Falha ao renomear: ' + err.message; statusEl.style.color = 'var(--danger)'; }
    }
}

// Leva direto pro cadastro completo do colaborador (Efetivo > Cadastros) - reaproveita
// o mesmo formulário/lógica de salvar já existente, em vez de duplicar campos aqui só
// pra edição rápida.
function editarColaboradorDaEquipe(matricula) {
    showDbPage('efetivo');
    showEfetivoSubtab('colaboradores');
    abrirFormEfetivo(matricula);
}

function filterEquipesAddColab(query) {
    const responsavel = document.getElementById('equipesResponsavelInput').value.trim();
    const container = document.getElementById('equipesAddColabResults');
    const q = (query || '').toLowerCase().trim();
    if (q.length < 2) { container.innerHTML = ''; return; }

    const matches = allEfetivo.filter(e =>
        colaboradorEstaAtivo(e) && e.responsavel !== responsavel &&
        ((e.nome && e.nome.toLowerCase().includes(q)) || (e.id && e.id.toLowerCase().includes(q)))
    ).slice(0, 15);

    if (matches.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum colaborador encontrado</div>';
        return;
    }
    container.innerHTML = matches.map(e => `
        <div class="db-list-item" style="cursor:pointer;" onclick="adicionarAEquipe('${escapeHTML(e.id)}')">
            <div class="db-list-item-title">${escapeHTML(e.nome || '')}</div>
            <div class="db-list-item-sub">${escapeHTML(e.funcao || '')} — Matrícula ${escapeHTML(e.id)}${e.responsavel ? ' — atualmente com ' + escapeHTML(e.responsavel) : ' — sem encarregado definido'}</div>
        </div>`).join('');
}

async function salvarResponsavelColaborador(matricula, novoResponsavel) {
    const statusEl = document.getElementById('equipesStatus');
    const e = allEfetivo.find(x => x.id === matricula);
    if (!e) return;
    if (statusEl) { statusEl.textContent = 'Salvando...'; statusEl.style.color = 'var(--text-light)'; }
    try {
        await supabaseUpsert('colaboradores_efetivo', [{ id: matricula, responsavel: novoResponsavel }]);
        e.responsavel = novoResponsavel;
        if (statusEl) { statusEl.textContent = '✅ Atualizado.'; statusEl.style.color = 'var(--success)'; }
        popularEquipesResponsavelDatalist();
        renderEquipeAtual();
    } catch (err) {
        console.error('Erro ao atualizar responsável do colaborador:', err);
        if (statusEl) { statusEl.textContent = '❌ Falha: ' + err.message; statusEl.style.color = 'var(--danger)'; }
    }
}

function adicionarAEquipe(matricula) {
    const responsavel = document.getElementById('equipesResponsavelInput').value.trim();
    if (!responsavel) return;
    salvarResponsavelColaborador(matricula, responsavel);
}

function removerDaEquipe(matricula) {
    if (!confirm('Remover este colaborador da equipe? Ele fica sem encarregado definido até ser adicionado a outra equipe.')) return;
    salvarResponsavelColaborador(matricula, null);
}

// ============================================
// CATÁLOGO DE TREINAMENTOS - cadastro/edição de tipo de treinamento (código, nome,
// carga horária, validade). Sem isso, a única forma de criar um código era a
// importação por CSV; agora dá pra criar/corrigir um treinamento direto no painel.
// Sem exclusão de propósito - códigos já usados em treinamentos_realizados/status não
// devem sumir do catálogo.
// ============================================

// Visão geral: total cadastrado, quantos têm validade (reciclagem) x quantos não
// (DDS pontuais) e a carga horária somada de todo o catálogo.
function renderCatalogoResumo() {
    const el = document.getElementById('catalogoResumo');
    if (!el) return;
    const total = allTreinamentosCatalogo.length;
    const comValidade = allTreinamentosCatalogo.filter(c => c.meses_validade).length;
    const cargaTotal = allTreinamentosCatalogo.reduce((sum, c) => sum + (parseFloat(c.carga_horaria) || 0), 0);
    el.textContent = total === 0 ? '' :
        `${total} treinamento(s) cadastrado(s) — ${comValidade} com validade (reciclagem), ${total - comValidade} sem validade — ${cargaTotal.toLocaleString('pt-BR')}h de carga horária somada`;
}

// 'todos' | 'com' | 'sem' - separa os ~20 treinamentos "de verdade" (NR/reciclagem, com
// meses_validade preenchido) dos ~153 tópicos de DDS pontuais (sem validade) misturados
// no mesmo catálogo de 172 itens - sem isso não tinha como achar só um grupo ou outro
// sem rolar a lista inteira.
let catalogoFiltroValidade = 'todos';

function setCatalogoFiltroValidade(valor) {
    catalogoFiltroValidade = valor;
    ['todos', 'com', 'sem'].forEach(v => document.getElementById(`catalogoFiltroBtn-${v}`)?.classList.toggle('active', v === valor));
    filterCatalogoTreinamentos(document.getElementById('catalogoSearchInput')?.value || '');
}

function filterCatalogoTreinamentos(query) {
    const container = document.getElementById('catalogoSearchResults');
    const q = (query || '').toLowerCase().trim();

    // Sem busca, mostra o catálogo inteiro (visão geral) em vez de ficar vazio até o
    // usuário digitar algo - a busca só entra pra estreitar a lista.
    const base = q.length < 2
        ? allTreinamentosCatalogo
        : allTreinamentosCatalogo.filter(c => (c.nome && c.nome.toLowerCase().includes(q)) || (c.id && c.id.toLowerCase().includes(q)));
    const porValidade = catalogoFiltroValidade === 'todos'
        ? base
        : base.filter(c => catalogoFiltroValidade === 'com' ? !!c.meses_validade : !c.meses_validade);
    const matches = porValidade.slice().sort((a, b) => (a.nome || '').localeCompare(b.nome || ''));

    if (matches.length === 0) {
        container.innerHTML = q.length < 2
            ? '<div class="db-list-empty">Nenhum treinamento cadastrado ainda</div>'
            : `<div class="db-list-empty">Nenhum treinamento encontrado para "${escapeHTML(query)}"</div>`;
        return;
    }
    container.innerHTML = matches.map(c => `
        <div class="db-list-item" style="cursor:pointer;" onclick="abrirFormCatalogoTreinamento('${escapeHTML(c.id)}')">
            <div class="db-list-item-title">${c.meses_validade ? '🔄 ' : ''}${escapeHTML(c.nome || '')}</div>
            <div class="db-list-item-sub">Código ${escapeHTML(c.id)} — ${c.carga_horaria || 0}h — ${c.meses_validade ? c.meses_validade + ' meses de validade' : 'Sem validade (avulso)'}</div>
        </div>`).join('');
}

// Banco de Questões (Prova) - editor de linha dinâmica, mesmo padrão de
// renderRiscosAprForm/renderRiscosGheForm (adicionar/remover linha, texto escreve
// direto no array sem re-render, só mudanças estruturais re-renderizam). Só
// treinamentos com pelo menos 1 questão salva ganham os botões de prova/gabarito em
// Registro (gerarProvaTurma/gerarGabaritoProva) - sem banco cadastrado, sem prova
// fabricada.
let catFormQuestoes = [];

function questaoVazia() {
    return { pergunta: '', alternativas: ['', '', '', ''], correta: 0 };
}

function adicionarQuestaoCatalogoForm() {
    catFormQuestoes.push(questaoVazia());
    renderQuestoesCatalogoForm();
}

function removerQuestaoCatalogoForm(i) {
    catFormQuestoes.splice(i, 1);
    renderQuestoesCatalogoForm();
}

function renderQuestoesCatalogoForm() {
    const container = document.getElementById('catFormQuestoesLista');
    if (!container) return;
    const campoEstilo = 'padding:6px; border:1px solid var(--border); border-radius:6px; font-size:11.5px; width:100%; box-sizing:border-box;';
    if (catFormQuestoes.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhuma questão cadastrada - clique em "➕ Adicionar Questão".</div>';
        return;
    }
    const letras = ['A', 'B', 'C', 'D'];
    container.innerHTML = catFormQuestoes.map((q, i) => `
        <div style="border:1px solid var(--border); border-radius:10px; padding:10px; margin-bottom:10px; background:var(--bg);">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
                <b style="font-size:12px;">Questão ${i + 1}</b>
                <button onclick="removerQuestaoCatalogoForm(${i})" title="Remover" style="border:none; background:none; color:var(--danger); cursor:pointer; font-size:15px;">🗑️</button>
            </div>
            <input type="text" placeholder="Pergunta" value="${escapeHTML(q.pergunta)}" oninput="catFormQuestoes[${i}].pergunta=this.value" style="${campoEstilo} margin-bottom:6px;">
            <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(160px,1fr)); gap:6px;">
                ${letras.map((letra, alt) => `
                    <div style="display:flex; align-items:center; gap:6px;">
                        <input type="radio" name="catFormQuestaoCorreta-${i}" ${q.correta === alt ? 'checked' : ''} onchange="catFormQuestoes[${i}].correta=${alt}" style="flex-shrink:0;">
                        <input type="text" placeholder="Alternativa ${letra}" value="${escapeHTML(q.alternativas[alt])}" oninput="catFormQuestoes[${i}].alternativas[${alt}]=this.value" style="${campoEstilo}">
                    </div>`).join('')}
            </div>
            <div style="font-size:10.5px; color:var(--text-light); margin-top:4px;">Marque o rádio da alternativa correta.</div>
        </div>`).join('');
}

function abrirFormCatalogoTreinamento(codigo) {
    const form = document.getElementById('catalogoFormCard');
    const title = document.getElementById('catalogoFormTitle');
    const codigoInput = document.getElementById('catForm_codigo');
    const btnExcluir = document.getElementById('catForm_btnExcluir');
    document.getElementById('catalogoFormStatus').textContent = '';
    document.getElementById('catForm_mesclarPanel').style.display = 'none';

    if (codigo) {
        const c = allTreinamentosCatalogo.find(x => x.id === codigo);
        if (!c) return;
        title.textContent = '✏️ Editar Treinamento';
        codigoInput.value = c.id || '';
        codigoInput.readOnly = true;
        codigoInput.style.background = 'var(--bg)';
        document.getElementById('catForm_nome').value = c.nome || '';
        document.getElementById('catForm_cargaHoraria').value = c.carga_horaria != null ? c.carga_horaria : '';
        document.getElementById('catForm_mesesValidade').value = c.meses_validade != null ? c.meses_validade : '';
        document.getElementById('catForm_metodoAvaliacao').value = c.metodo_avaliacao || 'Entendimento Participante';
        document.getElementById('catForm_objetivo').value = c.objetivo || '';
        document.getElementById('catForm_conteudoProgramatico').value = c.conteudo_programatico || '';
        document.getElementById('catForm_certificadoBaseLegal').value = c.certificado_base_legal || '';
        document.getElementById('catForm_integracaoBaseLegal').value = c.integracao_base_legal || '';
        document.getElementById('catForm_recusaBaseLegal').value = c.recusa_base_legal || '';
        document.getElementById('catForm_obrigacoesEmpresa').value = c.integracao_obrigacoes_empresa || '';
        document.getElementById('catForm_obrigacoesEmpregado').value = c.integracao_obrigacoes_empregado || '';
        document.getElementById('catForm_programaIntegracao').value = c.integracao_programa || '';
        catFormQuestoes = Array.isArray(c.questoes) ? c.questoes.map(q => ({ ...q, alternativas: [...(q.alternativas || ['', '', '', ''])] })) : [];
        renderQuestoesCatalogoForm();
        btnExcluir.style.display = 'inline-block';
    } else {
        title.textContent = '🎓 Novo Treinamento';
        codigoInput.value = '';
        codigoInput.readOnly = false;
        codigoInput.style.background = '';
        document.getElementById('catForm_nome').value = '';
        document.getElementById('catForm_cargaHoraria').value = '';
        document.getElementById('catForm_mesesValidade').value = '';
        document.getElementById('catForm_metodoAvaliacao').value = 'Entendimento Participante';
        document.getElementById('catForm_objetivo').value = '';
        document.getElementById('catForm_conteudoProgramatico').value = '';
        document.getElementById('catForm_certificadoBaseLegal').value = '';
        document.getElementById('catForm_integracaoBaseLegal').value = '';
        document.getElementById('catForm_recusaBaseLegal').value = '';
        document.getElementById('catForm_obrigacoesEmpresa').value = '';
        document.getElementById('catForm_obrigacoesEmpregado').value = '';
        document.getElementById('catForm_programaIntegracao').value = '';
        catFormQuestoes = [];
        renderQuestoesCatalogoForm();
        btnExcluir.style.display = 'none';
    }

    form.style.display = 'block';
    form.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function fecharFormCatalogoTreinamento() {
    document.getElementById('catalogoFormCard').style.display = 'none';
    document.getElementById('catForm_mesclarPanel').style.display = 'none';
}

function toggleExpandirCatalogo() {
    const el = document.getElementById('catalogoSearchResults');
    const btn = document.getElementById('btnExpandirCatalogo');
    const expandido = el.style.maxHeight === 'none';
    el.style.maxHeight = expandido ? '420px' : 'none';
    btn.textContent = expandido ? '⛶ Expandir Lista' : '⛶ Recolher Lista';
}

function limparBuscaCatalogo() {
    const input = document.getElementById('catalogoSearchInput');
    input.value = '';
    filterCatalogoTreinamentos('');
    input.focus();
}

// Exclusão (a pedido do usuário, após um caso real de código duplicado por erro de
// digitação: "79" e "128" com o mesmo conteúdo). Se o código nunca foi usado em nenhuma
// sessão, exclui direto. Se já foi usado, não dá pra simplesmente apagar - migra as
// sessões pro treinamento de destino escolhido primeiro (mesmo padrão da reconciliação
// de códigos sintéticos feita manualmente antes), senão o histórico dessas sessões
// ficaria com um treinamento_cod órfão, sem entrada correspondente no catálogo.
function iniciarExclusaoCatalogo() {
    const codigo = document.getElementById('catForm_codigo').value.trim();
    const cat = allTreinamentosCatalogo.find(c => c.id === codigo);
    if (!cat) return;
    const emUso = allTreinamentosRealizados.filter(r => r.treinamento_cod === codigo).length;

    if (emUso === 0) {
        if (!confirm(`Excluir "${cat.nome}" (código ${codigo}) do catálogo? Essa ação não pode ser desfeita.`)) return;
        excluirCatalogoDireto(codigo);
        return;
    }

    document.getElementById('catForm_mesclarAviso').innerHTML =
        `⚠️ <strong>"${escapeHTML(cat.nome)}"</strong> tem ${emUso} sessão(ões) já registrada(s). Pra excluir, escolha outro treinamento do catálogo pra migrar essas sessões antes (ex: se cadastrou duplicado por engano, migre pro código correto).`;
    document.getElementById('catForm_mesclarAlvo').value = '';
    document.getElementById('catForm_mesclarPanel').style.display = 'block';
}

async function excluirCatalogoDireto(codigo) {
    const statusEl = document.getElementById('catalogoFormStatus');
    statusEl.textContent = 'Excluindo...';
    statusEl.style.color = 'var(--text-light)';
    try {
        await supabaseDelete('treinamentos_catalogo', codigo);
        allTreinamentosCatalogo = allTreinamentosCatalogo.filter(c => c.id !== codigo);
        refreshCatalogoDatalist();
        renderCatalogoResumo();
        filterCatalogoTreinamentos(document.getElementById('catalogoSearchInput').value);
        statusEl.textContent = '✅ Excluído com sucesso.';
        statusEl.style.color = 'var(--success)';
        setTimeout(() => fecharFormCatalogoTreinamento(), 900);
    } catch (err) {
        console.error('Erro ao excluir treinamento do catálogo:', err);
        statusEl.textContent = '❌ Falha ao excluir: ' + err.message;
        statusEl.style.color = 'var(--danger)';
    }
}

async function confirmarMesclarExcluir() {
    const statusEl = document.getElementById('catalogoFormStatus');
    const origCodigo = document.getElementById('catForm_codigo').value.trim();
    const alvoCodigo = extrairCodigoTreinamento(document.getElementById('catForm_mesclarAlvo').value);

    if (!alvoCodigo || alvoCodigo === origCodigo) {
        statusEl.textContent = '❌ Escolha um treinamento de destino diferente do atual.';
        statusEl.style.color = 'var(--danger)';
        return;
    }
    const catAlvo = allTreinamentosCatalogo.find(c => c.id === alvoCodigo);
    if (!catAlvo) {
        statusEl.textContent = '❌ Treinamento de destino não encontrado no catálogo.';
        statusEl.style.color = 'var(--danger)';
        return;
    }

    const afetadas = allTreinamentosRealizados.filter(r => r.treinamento_cod === origCodigo);
    const linhasAtualizadas = afetadas.map(r => {
        let novaReciclagem = null;
        if (catAlvo.meses_validade && r.data_treinamento) {
            const d = parseLocalDate(r.data_treinamento);
            const alvo = new Date(d.getFullYear(), d.getMonth() + catAlvo.meses_validade, d.getDate());
            novaReciclagem = `${alvo.getFullYear()}-${String(alvo.getMonth() + 1).padStart(2, '0')}-${String(alvo.getDate()).padStart(2, '0')}`;
        }
        return {
            ...r,
            treinamento_cod: alvoCodigo,
            treinamento_nome: catAlvo.nome,
            carga_horaria: catAlvo.carga_horaria,
            meses_validade: catAlvo.meses_validade,
            data_proxima_reciclagem: novaReciclagem
        };
    });

    statusEl.textContent = `Migrando ${linhasAtualizadas.length} sessão(ões)...`;
    statusEl.style.color = 'var(--text-light)';
    try {
        if (linhasAtualizadas.length > 0) {
            await supabaseUpsert('treinamentos_realizados', linhasAtualizadas);
        }
        await supabaseDelete('treinamentos_catalogo', origCodigo);

        document.getElementById('catForm_mesclarPanel').style.display = 'none';
        statusEl.textContent = `✅ ${linhasAtualizadas.length} sessão(ões) migrada(s) para "${catAlvo.nome}" e treinamento antigo excluído.`;
        statusEl.style.color = 'var(--success)';

        treinamentosLoaded = true;
        await loadTreinamentosData();
        setTimeout(() => fecharFormCatalogoTreinamento(), 1800);
    } catch (err) {
        console.error('Erro ao mesclar/excluir treinamento:', err);
        statusEl.textContent = '❌ Falha ao mesclar: ' + err.message;
        statusEl.style.color = 'var(--danger)';
    }
}

async function salvarCatalogoTreinamento() {
    const statusEl = document.getElementById('catalogoFormStatus');
    const codigoInput = document.getElementById('catForm_codigo');
    const codigo = codigoInput.value.trim();
    const nome = document.getElementById('catForm_nome').value.trim();
    const cargaStr = document.getElementById('catForm_cargaHoraria').value;
    const mesesStr = document.getElementById('catForm_mesesValidade').value;

    if (!codigo || !nome || cargaStr === '') {
        statusEl.textContent = '❌ Código, nome e carga horária são obrigatórios.';
        statusEl.style.color = 'var(--danger)';
        return;
    }

    const isNovo = !codigoInput.readOnly;
    if (isNovo && allTreinamentosCatalogo.some(c => c.id === codigo)) {
        statusEl.textContent = '❌ Já existe um treinamento com esse código - busque por ele na lista acima pra editar.';
        statusEl.style.color = 'var(--danger)';
        return;
    }

    const row = {
        id: codigo,
        nome,
        carga_horaria: parseFloat(cargaStr),
        meses_validade: mesesStr !== '' ? parseInt(mesesStr, 10) : null,
        metodo_avaliacao: document.getElementById('catForm_metodoAvaliacao').value.trim() || 'Entendimento Participante',
        objetivo: document.getElementById('catForm_objetivo').value.trim() || null,
        conteudo_programatico: document.getElementById('catForm_conteudoProgramatico').value.trim() || null,
        certificado_base_legal: document.getElementById('catForm_certificadoBaseLegal').value.trim() || null,
        integracao_base_legal: document.getElementById('catForm_integracaoBaseLegal').value.trim() || null,
        recusa_base_legal: document.getElementById('catForm_recusaBaseLegal').value.trim() || null,
        integracao_obrigacoes_empresa: document.getElementById('catForm_obrigacoesEmpresa').value.trim() || null,
        integracao_obrigacoes_empregado: document.getElementById('catForm_obrigacoesEmpregado').value.trim() || null,
        integracao_programa: document.getElementById('catForm_programaIntegracao').value.trim() || null,
        questoes: catFormQuestoes.filter(q => (q.pergunta || '').trim() && q.alternativas.every(a => (a || '').trim()))
    };

    statusEl.textContent = 'Salvando...';
    statusEl.style.color = 'var(--text-light)';
    try {
        await supabaseUpsert('treinamentos_catalogo', [row]);
        const idx = allTreinamentosCatalogo.findIndex(c => c.id === codigo);
        if (idx >= 0) allTreinamentosCatalogo[idx] = { ...allTreinamentosCatalogo[idx], ...row };
        else allTreinamentosCatalogo.push(row);

        refreshCatalogoDatalist();
        filterCatalogoTreinamentos(document.getElementById('catalogoSearchInput').value);
        renderCatalogoResumo();

        statusEl.textContent = '✅ Salvo com sucesso.';
        statusEl.style.color = 'var(--success)';
        setTimeout(() => fecharFormCatalogoTreinamento(), 900);
    } catch (err) {
        console.error('Erro ao salvar treinamento no catálogo:', err);
        statusEl.textContent = '❌ Falha ao salvar: ' + err.message;
        statusEl.style.color = 'var(--danger)';
    }
}

// ============================================
// EFETIVO (Parte B) - replica as fórmulas já usadas na aba TBs_DINAMICAS da
// planilha TREINAMENTOS_EFETIVO.xlsx: admissões/demissões por COUNTIF de mês,
// efetivo real como headcount na data, índice = HHT do mês ÷ efetivo do mês × 100.
// ============================================

let allEfetivo = [];
let allGheCatalogo = [];
let efetivoLoaded = false;

async function loadEfetivoData() {
    const statusEl = document.getElementById('efetivoImportStatus');
    try {
        allEfetivo = await supabaseFetch('colaboradores_efetivo', '?select=*');
        allGheCatalogo = await supabaseFetch('ghe_catalogo', '?select=*');
        popularGheCatalogoDatalist();
        if (!treinamentosLoaded) {
            treinamentosLoaded = true;
            await loadTreinamentosData();
        }
        renderEfetivoPanel();
        renderEfetivoResumo();
        filterEfetivoColaboradores(document.getElementById('efetivoSearchInput')?.value || '');
    } catch (err) {
        console.error('Erro ao carregar dados de efetivo:', err);
        if (statusEl) statusEl.textContent = '❌ Falha ao carregar dados de efetivo.';
    }
}

// Abas da página Efetivo (Visão Geral / Colaboradores) - mesmo raciocínio de
// self-heal do showTreinSubtab: sempre re-renderiza a Visão Geral ao entrar nela.
function showEfetivoSubtab(tab) {
    ['visao', 'colaboradores', 'setores', 'ghe', 'recomendacoes'].forEach(t => {
        const content = document.getElementById('efetivoSubtab-' + t);
        const btn = document.getElementById('efetivoSubtabBtn-' + t);
        if (content) content.style.display = (t === tab) ? 'block' : 'none';
        if (btn) btn.classList.toggle('active', t === tab);
    });
    if (tab === 'visao') renderEfetivoPanel();
    if (tab === 'setores') { fecharGerenciarSetor(); renderSetoresLista(); }
    if (tab === 'ghe') { fecharGerenciarGhe(); renderGheLista(); }
    if (tab === 'recomendacoes') renderRecomendacoesGheLista();
}

// ============================================
// SETORES - mesmo raciocínio de Gestão de Equipes (Treinamentos), só que pro campo
// "setor" em vez de "responsavel". Setor não é uma tabela própria - é só um campo texto
// em colaboradores_efetivo, então "criar um setor" é só abrir o painel de gestão com um
// nome novo (fica de verdade a partir do primeiro colaborador movido pra ele), e
// "renomear" é um UPDATE em lote de todo mundo que está com aquele texto hoje.
// ============================================

let setorAtualGerenciado = null;

function renderSetoresLista() {
    const container = document.getElementById('setoresLista');
    const resumo = document.getElementById('setoresResumo');
    if (!container) return;

    const contagem = new Map();
    allEfetivo.forEach(e => {
        if (!colaboradorEstaAtivo(e) || !e.setor) return;
        contagem.set(e.setor, (contagem.get(e.setor) || 0) + 1);
    });
    const setores = Array.from(contagem.entries()).sort((a, b) => a[0].localeCompare(b[0]));

    if (resumo) resumo.textContent = `${setores.length} setor(es) em uso`;

    if (setores.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum setor cadastrado ainda.</div>';
        return;
    }
    container.innerHTML = setores.map(([nome, qtd]) => `
        <div class="db-list-item" style="cursor:pointer;" onclick="abrirGerenciarSetor('${escapeHTML(nome)}')">
            <div class="db-list-item-title">${escapeHTML(nome)}</div>
            <div class="db-list-item-sub">${qtd} colaborador(es)</div>
        </div>`).join('');
}

function criarNovoSetor() {
    const nome = prompt('Nome do novo setor:');
    if (!nome || !nome.trim()) return;
    abrirGerenciarSetor(nome.trim().toUpperCase());
}

function abrirGerenciarSetor(nomeSetor) {
    setorAtualGerenciado = nomeSetor;
    document.getElementById('setorGerenciarTitulo').textContent = '🏢 ' + nomeSetor;
    document.getElementById('setorGerenciarStatus').textContent = '';
    document.getElementById('setorAddColabInput').value = '';
    document.getElementById('setorAddColabResults').innerHTML = '';
    document.getElementById('setorGerenciarCard').style.display = 'block';
    renderSetorColabList();
    document.getElementById('setorGerenciarCard').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function fecharGerenciarSetor() {
    setorAtualGerenciado = null;
    const card = document.getElementById('setorGerenciarCard');
    if (card) card.style.display = 'none';
}

function renderSetorColabList() {
    const container = document.getElementById('setorColabList');
    if (!container || !setorAtualGerenciado) return;
    const equipe = allEfetivo.filter(e => colaboradorEstaAtivo(e) && e.setor === setorAtualGerenciado)
        .sort((a, b) => (a.nome || '').localeCompare(b.nome || ''));

    if (equipe.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum colaborador neste setor ainda.</div>';
        return;
    }
    container.innerHTML = equipe.map(e => `
        <div class="db-list-item" style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
            <div>
                <div class="db-list-item-title">${escapeHTML(e.nome || '')}</div>
                <div class="db-list-item-sub">${escapeHTML(e.funcao || '')} — Matrícula ${escapeHTML(e.id)}</div>
            </div>
            <div style="display:flex; gap:6px; flex-shrink:0;">
                <button class="db-clear-btn" onclick="editarColaboradorDaEquipe('${escapeHTML(e.id)}')">✏️ Editar</button>
                <button class="db-clear-btn" style="color:var(--danger); border-color:var(--danger);" onclick="removerDoSetor('${escapeHTML(e.id)}')">Remover</button>
            </div>
        </div>`).join('');
}

function filterSetorAddColab(query) {
    const container = document.getElementById('setorAddColabResults');
    const q = (query || '').toLowerCase().trim();
    if (q.length < 2) { container.innerHTML = ''; return; }

    const matches = allEfetivo.filter(e =>
        colaboradorEstaAtivo(e) && e.setor !== setorAtualGerenciado &&
        ((e.nome && e.nome.toLowerCase().includes(q)) || (e.id && e.id.toLowerCase().includes(q)))
    ).slice(0, 15);

    if (matches.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum colaborador encontrado</div>';
        return;
    }
    container.innerHTML = matches.map(e => `
        <div class="db-list-item" style="cursor:pointer;" onclick="adicionarAoSetor('${escapeHTML(e.id)}')">
            <div class="db-list-item-title">${escapeHTML(e.nome || '')}</div>
            <div class="db-list-item-sub">${escapeHTML(e.funcao || '')} — Matrícula ${escapeHTML(e.id)}${e.setor ? ' — atualmente em ' + escapeHTML(e.setor) : ' — sem setor definido'}</div>
        </div>`).join('');
}

async function salvarSetorColaborador(matricula, novoSetor) {
    const statusEl = document.getElementById('setorGerenciarStatus');
    const e = allEfetivo.find(x => x.id === matricula);
    if (!e) return;
    if (statusEl) { statusEl.textContent = 'Salvando...'; statusEl.style.color = 'var(--text-light)'; }
    try {
        await supabaseUpsert('colaboradores_efetivo', [{ id: matricula, setor: novoSetor }]);
        e.setor = novoSetor;
        if (statusEl) { statusEl.textContent = '✅ Atualizado.'; statusEl.style.color = 'var(--success)'; }
        renderSetorColabList();
        renderSetoresLista();
    } catch (err) {
        console.error('Erro ao atualizar setor do colaborador:', err);
        if (statusEl) { statusEl.textContent = '❌ Falha: ' + err.message; statusEl.style.color = 'var(--danger)'; }
    }
}

function adicionarAoSetor(matricula) {
    if (!setorAtualGerenciado) return;
    salvarSetorColaborador(matricula, setorAtualGerenciado);
    document.getElementById('setorAddColabInput').value = '';
    document.getElementById('setorAddColabResults').innerHTML = '';
}

function removerDoSetor(matricula) {
    if (!confirm('Remover este colaborador do setor? Ele fica sem setor definido até ser adicionado a outro.')) return;
    salvarSetorColaborador(matricula, null);
}

async function renomearSetor() {
    if (!setorAtualGerenciado) return;
    const novoNome = prompt(`Renomear "${setorAtualGerenciado}" para:`, setorAtualGerenciado);
    if (!novoNome || !novoNome.trim() || novoNome.trim() === setorAtualGerenciado) return;
    const nomeFinal = novoNome.trim().toUpperCase();

    const afetados = allEfetivo.filter(e => e.setor === setorAtualGerenciado);
    const statusEl = document.getElementById('setorGerenciarStatus');
    statusEl.textContent = `Renomeando ${afetados.length} colaborador(es)...`;
    statusEl.style.color = 'var(--text-light)';
    try {
        const linhas = afetados.map(e => ({ id: e.id, setor: nomeFinal }));
        if (linhas.length > 0) await supabaseUpsert('colaboradores_efetivo', linhas);
        afetados.forEach(e => { e.setor = nomeFinal; });
        setorAtualGerenciado = nomeFinal;
        document.getElementById('setorGerenciarTitulo').textContent = '🏢 ' + nomeFinal;
        statusEl.textContent = `✅ ${afetados.length} colaborador(es) movido(s) pra "${nomeFinal}".`;
        statusEl.style.color = 'var(--success)';
        renderSetorColabList();
        renderSetoresLista();
    } catch (err) {
        console.error('Erro ao renomear setor:', err);
        statusEl.textContent = '❌ Falha: ' + err.message;
        statusEl.style.color = 'var(--danger)';
    }
}

// ============================================
// GHE (Grupo Homogêneo de Exposição) - catálogo oficial importado do Quadro Funcional
// da empresa (ver importarQuadroFuncionalXLS), comparado com a quantidade real de
// colaboradores ativos hoje em colaboradores_efetivo.ghe. Mesmo raciocínio de
// gerenciamento de Setores acima, só que "criar um grupo" não existe aqui - o catálogo
// só nasce da importação da planilha oficial, nunca é criado manualmente. Independente
// do GHE usado no PCMSO (PCMSO_SETOR_FUNCAO_GHE, mais acima), que resolve por
// setor+função e não lê este campo.
// ============================================

let gheAtualGerenciado = null;

// colaboradores_efetivo.ghe é texto livre - normaliza número solto ("1") pro mesmo
// formato de 2 dígitos usado no catálogo ("01") antes de comparar.
function normalizarGhe(v) {
    const s = String(v || '').trim();
    return /^\d+$/.test(s) ? s.padStart(2, '0') : s;
}

function contagemAtualPorGhe() {
    const contagem = new Map();
    allEfetivo.forEach(e => {
        if (!colaboradorEstaAtivo(e) || !e.ghe) return;
        const chave = normalizarGhe(e.ghe);
        contagem.set(chave, (contagem.get(chave) || 0) + 1);
    });
    return contagem;
}

function renderGheLista() {
    const container = document.getElementById('gheLista');
    const resumo = document.getElementById('gheResumo');
    if (!container) return;

    if (allGheCatalogo.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum catálogo de GHE importado ainda. Envie o Quadro Funcional em Configurações.</div>';
        if (resumo) resumo.textContent = '';
        return;
    }

    const contagem = contagemAtualPorGhe();
    const grupos = allGheCatalogo.slice().sort((a, b) => a.id.localeCompare(b.id));
    const totalOficial = grupos.reduce((s, g) => s + (g.quantidade_oficial || 0), 0);
    const totalAtual = Array.from(contagem.values()).reduce((s, v) => s + v, 0);
    if (resumo) resumo.textContent = `${grupos.length} grupo(s) do quadro oficial — ${totalOficial} pessoa(s) no quadro, ${totalAtual} ativo(s) hoje classificado(s) por GHE`;

    container.innerHTML = grupos.map(g => {
        const atual = contagem.get(g.id) || 0;
        const oficial = g.quantidade_oficial || 0;
        const delta = atual - oficial;
        let corDelta = 'var(--success)', textoDelta = '✓ bate com o quadro';
        if (delta > 0) { corDelta = 'var(--text-light)'; textoDelta = `+${delta} a mais que o quadro`; }
        else if (delta < 0) { corDelta = 'var(--danger)'; textoDelta = `${delta} a menos que o quadro`; }
        return `<div class="db-list-item" style="cursor:pointer;" onclick="abrirGerenciarGhe('${escapeHTML(g.id)}')">
            <div class="db-list-item-title">${escapeHTML(g.id)} — ${escapeHTML(g.nome)}</div>
            <div class="db-list-item-sub">Oficial: ${oficial} — Atual: ${atual} — <span style="color:${corDelta}; font-weight:600;">${textoDelta}</span></div>
        </div>`;
    }).join('');
}

// Fonte: Mapa de Riscos oficial (Clínica ENGMED, PGR/NR-01), reconhecimento por GHE -
// não é o mesmo dado da matriz P×S da APR (que é por tarefa/equipe, não por
// função/setor). A maioria dos GHEs administrativos legitimamente não tem exposição
// significativa segundo o laudo ("Não foram identificados riscos significativos") -
// riscos=[] nesses casos reflete o próprio laudo, não é campo vazio por preguiça.
function gravidadeGheEstilo(g) {
    const n = parseInt(g, 10);
    if (n <= 1) return { cor: '#1a7f4b', bg: '#e6f7ee' };
    if (n === 2) return { cor: '#c2650a', bg: '#fef1e0' };
    return { cor: '#c0392b', bg: '#fdf2f2' };
}

function renderGheMapaRiscosHtml(g) {
    const riscos = Array.isArray(g.riscos) ? g.riscos : [];
    const c = g.conclusoes || {};
    const temConclusao = c.gfip_codigo || c.gfip_descricao || c.periculosidade || c.insalubridade;
    const conclusaoHtml = temConclusao ? `
        <div style="border:1px solid var(--border); border-radius:10px; padding:10px; margin-bottom:10px; font-size:12px; background:var(--bg);">
            <div style="font-weight:700; margin-bottom:4px;">📋 Conclusões</div>
            ${(c.gfip_codigo || c.gfip_descricao) ? `<div><b>GFIP ${escapeHTML(c.gfip_codigo || '')}:</b> ${escapeHTML(c.gfip_descricao || '')}</div>` : ''}
            ${c.periculosidade ? `<div><b>Periculosidade:</b> ${escapeHTML(c.periculosidade)}</div>` : ''}
            ${c.insalubridade ? `<div><b>Insalubridade:</b> ${escapeHTML(c.insalubridade)}</div>` : ''}
        </div>` : '';

    if (riscos.length === 0) {
        return conclusaoHtml + '<div class="db-list-empty">✅ Não foram identificados riscos significativos para este grupo (conforme laudo do Mapa de Riscos).</div>';
    }
    return conclusaoHtml + riscos.map(r => {
        // Colore pelo gravidade_label (mesma fonte que KPIs/gráfico/lista de Riscos Altos
        // usam), não mais só pelo número de gravidade - gravidadeGheEstilo() assumia uma
        // escala pequena (1-3, do laudo original importado), que não bate mais com o valor
        // de 1-25 (probabilidade × severidade) que um risco reclassificado pelos novos
        // campos passa a ter. Cai pra gravidadeGheEstilo() só se o rótulo não for
        // reconhecido (dado antigo sem gravidade_label).
        const grav = NIVEIS_RISCO_COR[r.gravidade_label]
            ? { cor: NIVEIS_RISCO_COR[r.gravidade_label], bg: NIVEIS_RISCO_COR[r.gravidade_label] + '22' }
            : gravidadeGheEstilo(r.gravidade);
        return `<div style="border:1px solid var(--border); border-radius:10px; padding:10px; margin-bottom:8px;">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:6px;">
                <div><b>${escapeHTML(r.tipo_agente || '')}</b> — ${escapeHTML(r.agente || '')}</div>
                <span style="padding:3px 10px; border-radius:12px; background:${grav.bg}; color:${grav.cor}; font-weight:700; font-size:11px;">
                    Gravidade ${escapeHTML(String(r.gravidade ?? ''))} - ${escapeHTML(r.gravidade_label || '')}
                </span>
            </div>
            <div style="font-size:12px; color:var(--text-light); margin-bottom:4px;">${escapeHTML(r.descricao || '')}</div>
            <div style="font-size:12px;"><b>Danos à saúde:</b> ${escapeHTML(r.danos_saude || '—')}</div>
            <div style="font-size:12px;"><b>Fontes geradoras:</b> ${escapeHTML(r.fontes_geradoras || '—')}${r.tipo_tempo_exposicao ? ` · <b>Exposição:</b> ${escapeHTML(r.tipo_tempo_exposicao)}` : ''}</div>
            <div style="font-size:12px;"><b>Medidas/sugestões:</b> ${escapeHTML(r.sugestoes || '—')}</div>
            ${r.epis_recomendados ? `<div style="font-size:12px;"><b>EPIs recomendados:</b> ${escapeHTML(r.epis_recomendados)}</div>` : ''}
            ${r.epcs_recomendados ? `<div style="font-size:12px;"><b>EPCs recomendados:</b> ${escapeHTML(r.epcs_recomendados)}</div>` : ''}
            ${r.situacao_controle ? `<div style="font-size:11px; color:var(--text-light); margin-top:4px;">Situação de controle: ${escapeHTML(r.situacao_controle)}</div>` : ''}
        </div>`;
    }).join('');
}

// Expande em linha o painel de edição completo do cargo clicado (Cargo/Função/CBO,
// Descrição das Atividades, Agentes, EPIs/EPCs, Recomendações etc.) - mesmo padrão de
// expandir-em-linha já usado em Compras/APR, em vez de modal. Toda linha é clicável,
// mesmo cargo recém-adicionado manualmente e ainda sem nenhum campo preenchido - antes
// só abria quem já tinha descricao_atividade ou cbo (vindo da planilha oficial), o que
// tornava impossível editar/criar um cargo à mão.
let gheCargoExpandidoIdx = null;

function toggleCargoGheDescricao(idx) {
    gheCargoExpandidoIdx = gheCargoExpandidoIdx === idx ? null : idx;
    const g = allGheCatalogo.find(x => x.id === gheAtualGerenciado);
    if (g) document.getElementById('gheCargosOficiais').innerHTML = renderGheCargosHtml(g);
}

// Cargo em branco pro "+ Adicionar cargo" - mesmas chaves de um cargo vindo da
// importação da planilha oficial, só que todas vazias pra preencher na hora.
function cargoGheVazio() {
    return {
        cargo: '', funcao: '', cbo: '', quantidade: '', descricao_atividade: '',
        agentes: { fisico: '', quimico: '', biologico: '', ergonomico: '', acidentes: '' },
        epis_necessarios: [], epcs_necessarios: [], recomendacoes: '', procedimentos_acidentes: '', observacoes: ''
    };
}

function adicionarCargoGhe() {
    const g = allGheCatalogo.find(x => x.id === gheAtualGerenciado);
    if (!g) return;
    if (!Array.isArray(g.cargos)) g.cargos = [];
    g.cargos.push(cargoGheVazio());
    gheCargoExpandidoIdx = g.cargos.length - 1; // já abre expandido pra preencher na hora
    document.getElementById('gheCargosOficiais').innerHTML = renderGheCargosHtml(g);
    document.getElementById('gheCargosOficiais').scrollIntoView({ behavior: 'smooth', block: 'end' });
}

// Sugestões (datalist) coletadas de QUALQUER cargo de QUALQUER grupo de GHE - digitar
// continua livre (datalist não trava a digitação, só sugere), mas reaproveitar o que já
// existe evita duas entradas diferentes no sistema por causa de uma diferença mínima de
// digitação (ex: "Capacete de Segurança" vs "Capacete Segurança"), que atrapalhava
// qualquer contagem/padronização (achado real reportado pelo usuário).
function coletarSugestoesGheCargos(extrair) {
    const valores = new Set();
    allGheCatalogo.forEach(g => (Array.isArray(g.cargos) ? g.cargos : []).forEach(c => {
        const v = extrair(c);
        (Array.isArray(v) ? v : [v]).forEach(item => { if (item && String(item).trim()) valores.add(String(item).trim()); });
    }));
    return Array.from(valores).sort((a, b) => a.localeCompare(b));
}

function optsDatalistGhe(valores) {
    return valores.map(v => `<option value="${escapeHTML(v)}">`).join('');
}

// Lista de EPI/EPC de cada cargo em edição - array de strings por índice do cargo (não
// mais textarea "um item por linha"), montada por adicionarGheCargoItem/
// removerGheCargoItem e só vira epis_necessarios/epcs_necessarios de fato no momento de
// salvarCargoAgentesEpi. Resemeada a partir do cargo salvo sempre que a linha (re)abre —
// os 3 pontos que chamam renderGheCargosHtml com uma linha expandida (toggleCargoGheDescricao,
// adicionarCargoGhe, salvarCargoAgentesEpi pós-salvar) - mesmo comportamento que os demais
// campos já têm hoje (fecha sem salvar = perde a edição em andamento).
let gheCargoEpisForm = {};
let gheCargoEpcsForm = {};

function htmlGheCargoItens(i, tipo) {
    const estado = (tipo === 'epis' ? gheCargoEpisForm : gheCargoEpcsForm)[i] || [];
    return estado.length === 0
        ? '<div class="db-list-empty" style="padding:6px 0; font-size:11px;">Nenhum item adicionado.</div>'
        : estado.map((item, idx) => `
            <div class="db-list-item" style="display:flex; align-items:center; justify-content:space-between; gap:6px; padding:5px 8px;">
                <span>${escapeHTML(item)}</span>
                <button type="button" onclick="removerGheCargoItem(${i}, '${tipo}', ${idx})" title="Remover" style="border:none; background:none; color:var(--danger); cursor:pointer; font-size:13px;">✕</button>
            </div>`).join('');
}

function renderGheCargoItemsLista(i, tipo) {
    const container = document.getElementById(tipo === 'epis' ? `gheCargoEpisLista-${i}` : `gheCargoEpcsLista-${i}`);
    if (container) container.innerHTML = htmlGheCargoItens(i, tipo);
}

function adicionarGheCargoItem(i, tipo) {
    const input = document.getElementById(tipo === 'epis' ? `gheCargoEpiInput-${i}` : `gheCargoEpcInput-${i}`);
    const valor = (input.value || '').trim();
    if (!valor) return;
    const estado = tipo === 'epis' ? gheCargoEpisForm : gheCargoEpcsForm;
    if (!Array.isArray(estado[i])) estado[i] = [];
    if (!estado[i].includes(valor)) estado[i].push(valor);
    input.value = '';
    renderGheCargoItemsLista(i, tipo);
}

function removerGheCargoItem(i, tipo, idx) {
    const estado = tipo === 'epis' ? gheCargoEpisForm : gheCargoEpcsForm;
    if (!Array.isArray(estado[i])) return;
    estado[i].splice(idx, 1);
    renderGheCargoItemsLista(i, tipo);
}

// Copia os campos preenchíveis (tudo, menos Cargo/Função/CBO/Qtd., que identificam ESTE
// cargo) de outro cargo já cadastrado NO MESMO GRUPO pro formulário atual - só nos campos
// (ainda não salvos), pra dar pra revisar/ajustar antes de "💾 Salvar". Motivado por um
// caso real: GRUPO 16 tinha "Técnico de enfermagem em saúde ocupacional" completo, mas
// "TEC. ENFERMEIRO DO TRABALHO" (a função real da colaboradora) ficou sem essas
// informações - digitar tudo de novo na mão era o único jeito antes disso.
function copiarCargoGhe(i) {
    const g = allGheCatalogo.find(x => x.id === gheAtualGerenciado);
    if (!g || !Array.isArray(g.cargos)) return;
    const sel = document.getElementById(`gheCargoCopiarDe-${i}`);
    const origemIdx = parseInt(sel?.value, 10);
    const origem = g.cargos[origemIdx];
    if (!origem) return;
    const nomeOrigem = origem.cargo || origem.funcao || '(sem cargo)';
    if (!confirm(`Copiar os dados de "${nomeOrigem}" pro formulário abaixo? Isso substitui o que estiver preenchido nos campos (ainda não salvos) - revise e clique em "💾 Salvar" pra confirmar.`)) return;

    document.getElementById(`gheCargoDescricaoAtividade-${i}`).value = origem.descricao_atividade || '';
    const ag = origem.agentes || {};
    document.getElementById(`gheCargoFisico-${i}`).value = ag.fisico || '';
    document.getElementById(`gheCargoQuimico-${i}`).value = ag.quimico || '';
    document.getElementById(`gheCargoBiologico-${i}`).value = ag.biologico || '';
    document.getElementById(`gheCargoErgonomico-${i}`).value = ag.ergonomico || '';
    document.getElementById(`gheCargoAcidentes-${i}`).value = ag.acidentes || '';
    document.getElementById(`gheCargoRecomendacoes-${i}`).value = origem.recomendacoes || '';
    document.getElementById(`gheCargoProcedimentosAcidentes-${i}`).value = origem.procedimentos_acidentes || '';
    document.getElementById(`gheCargoObservacoes-${i}`).value = origem.observacoes || '';
    gheCargoEpisForm[i] = Array.isArray(origem.epis_necessarios) ? [...origem.epis_necessarios] : [];
    gheCargoEpcsForm[i] = Array.isArray(origem.epcs_necessarios) ? [...origem.epcs_necessarios] : [];
    renderGheCargoItemsLista(i, 'epis');
    renderGheCargoItemsLista(i, 'epcs');
}

function renderGheCargosHtml(g) {
    const cargos = Array.isArray(g.cargos) ? g.cargos : [];
    if (cargos.length === 0) return '<div class="db-list-empty">Sem cargos cadastrados neste grupo ainda - use "+ Adicionar cargo" acima.</div>';
    const campoMini = 'padding:5px 6px; border:1px solid var(--border); border-radius:6px; font-size:11px; width:100%; box-sizing:border-box;';
    const sugestoesFisico = optsDatalistGhe(coletarSugestoesGheCargos(c => (c.agentes || {}).fisico));
    const sugestoesQuimico = optsDatalistGhe(coletarSugestoesGheCargos(c => (c.agentes || {}).quimico));
    const sugestoesBiologico = optsDatalistGhe(coletarSugestoesGheCargos(c => (c.agentes || {}).biologico));
    const sugestoesErgonomico = optsDatalistGhe(coletarSugestoesGheCargos(c => (c.agentes || {}).ergonomico));
    const sugestoesAcidentes = optsDatalistGhe(coletarSugestoesGheCargos(c => (c.agentes || {}).acidentes));
    const sugestoesEpi = optsDatalistGhe(coletarSugestoesGheCargos(c => c.epis_necessarios));
    const sugestoesEpc = optsDatalistGhe(coletarSugestoesGheCargos(c => c.epcs_necessarios));
    return `<table style="width:100%; border-collapse:collapse; font-size:12px;">
        <thead><tr style="text-align:left; color:var(--text-light);">
            <th style="padding:4px 4px; width:18px;"></th><th style="padding:4px 8px;">Cargo</th><th style="padding:4px 8px;">Função</th><th style="padding:4px 8px;">CBO</th><th style="padding:4px 8px;">Qtd. oficial</th>
        </tr></thead>
        <tbody>${cargos.map((c, i) => {
            const expandido = gheCargoExpandidoIdx === i;
            const ag = c.agentes || {};
            if (expandido) {
                gheCargoEpisForm[i] = Array.isArray(c.epis_necessarios) ? [...c.epis_necessarios] : [];
                gheCargoEpcsForm[i] = Array.isArray(c.epcs_necessarios) ? [...c.epcs_necessarios] : [];
            }
            const outrosCargos = cargos.map((c2, idx2) => [idx2, c2]).filter(([idx2]) => idx2 !== i);
            const linhaDetalhe = expandido ? `<tr><td></td><td colspan="4" style="padding:4px 8px 14px;" onclick="event.stopPropagation()">
                <div style="font-weight:600; font-size:11px; margin-bottom:4px;">Identificação do cargo</div>
                <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(140px,1fr)); gap:6px; margin-bottom:8px;">
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Cargo</label><input type="text" id="gheCargoCargo-${i}" value="${escapeHTML(c.cargo || '')}" style="${campoMini}"></div>
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Função (comparada com colaboradores_efetivo.funcao)</label><input type="text" id="gheCargoFuncao-${i}" value="${escapeHTML(c.funcao || '')}" style="${campoMini}"></div>
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">CBO</label><input type="text" id="gheCargoCbo-${i}" value="${escapeHTML(c.cbo || '')}" style="${campoMini}"></div>
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Qtd. oficial</label><input type="text" id="gheCargoQuantidade-${i}" value="${escapeHTML(String(c.quantidade ?? ''))}" style="${campoMini}"></div>
                </div>
                ${outrosCargos.length > 0 ? `<div style="display:flex; align-items:flex-end; gap:6px; margin-bottom:8px;">
                    <div style="flex:1;"><label style="color:var(--text-light); font-size:10.5px; display:block;">Copiar de:</label>
                        <select id="gheCargoCopiarDe-${i}" style="${campoMini}">
                            ${outrosCargos.map(([idx2, c2]) => `<option value="${idx2}">${escapeHTML(c2.cargo || c2.funcao || '(sem cargo)')}</option>`).join('')}
                        </select>
                    </div>
                    <button type="button" class="db-clear-btn" style="padding:5px 10px; font-size:11px; white-space:nowrap;" onclick="copiarCargoGhe(${i})">📋 Copiar</button>
                </div>` : ''}
                <div style="margin-bottom:8px;"><label style="color:var(--text-light); font-size:10.5px; display:block;">Descrição das Atividades</label><textarea id="gheCargoDescricaoAtividade-${i}" rows="2" style="${campoMini}">${escapeHTML(c.descricao_atividade || '')}</textarea></div>
                <div style="font-weight:600; font-size:11px; margin-bottom:4px;">Agentes associados às atividades (usado na Ordem de Serviço)</div>
                <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(140px,1fr)); gap:6px; margin-bottom:8px;">
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Físico</label><input type="text" id="gheCargoFisico-${i}" list="gheAgenteFisicoSugestoes" value="${escapeHTML(ag.fisico || '')}" style="${campoMini}"></div>
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Químico</label><input type="text" id="gheCargoQuimico-${i}" list="gheAgenteQuimicoSugestoes" value="${escapeHTML(ag.quimico || '')}" style="${campoMini}"></div>
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Biológico</label><input type="text" id="gheCargoBiologico-${i}" list="gheAgenteBiologicoSugestoes" value="${escapeHTML(ag.biologico || '')}" style="${campoMini}"></div>
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Ergonômico</label><input type="text" id="gheCargoErgonomico-${i}" list="gheAgenteErgonomicoSugestoes" value="${escapeHTML(ag.ergonomico || '')}" style="${campoMini}"></div>
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Acidentes</label><input type="text" id="gheCargoAcidentes-${i}" list="gheAgenteAcidentesSugestoes" value="${escapeHTML(ag.acidentes || '')}" style="${campoMini}"></div>
                </div>
                <datalist id="gheAgenteFisicoSugestoes">${sugestoesFisico}</datalist>
                <datalist id="gheAgenteQuimicoSugestoes">${sugestoesQuimico}</datalist>
                <datalist id="gheAgenteBiologicoSugestoes">${sugestoesBiologico}</datalist>
                <datalist id="gheAgenteErgonomicoSugestoes">${sugestoesErgonomico}</datalist>
                <datalist id="gheAgenteAcidentesSugestoes">${sugestoesAcidentes}</datalist>
                <datalist id="gheEpiSugestoes">${sugestoesEpi}</datalist>
                <datalist id="gheEpcSugestoes">${sugestoesEpc}</datalist>
                <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(200px,1fr)); gap:6px; margin-bottom:8px;">
                    <div>
                        <label style="color:var(--text-light); font-size:10.5px; display:block;">EPIs necessários</label>
                        <div style="display:flex; gap:6px; margin-bottom:4px;">
                            <input type="text" id="gheCargoEpiInput-${i}" list="gheEpiSugestoes" placeholder="Digite ou selecione um EPI..." style="${campoMini}">
                            <button type="button" class="db-clear-btn" style="padding:5px 10px; font-size:11px; white-space:nowrap;" onclick="adicionarGheCargoItem(${i}, 'epis')">+ Adicionar</button>
                        </div>
                        <div id="gheCargoEpisLista-${i}" style="display:flex; flex-direction:column; gap:4px; max-height:140px; overflow-y:auto;">${htmlGheCargoItens(i, 'epis')}</div>
                    </div>
                    <div>
                        <label style="color:var(--text-light); font-size:10.5px; display:block;">EPCs necessários</label>
                        <div style="display:flex; gap:6px; margin-bottom:4px;">
                            <input type="text" id="gheCargoEpcInput-${i}" list="gheEpcSugestoes" placeholder="Digite ou selecione um EPC..." style="${campoMini}">
                            <button type="button" class="db-clear-btn" style="padding:5px 10px; font-size:11px; white-space:nowrap;" onclick="adicionarGheCargoItem(${i}, 'epcs')">+ Adicionar</button>
                        </div>
                        <div id="gheCargoEpcsLista-${i}" style="display:flex; flex-direction:column; gap:4px; max-height:140px; overflow-y:auto;">${htmlGheCargoItens(i, 'epcs')}</div>
                    </div>
                </div>
                <div style="font-weight:600; font-size:11px; margin-bottom:4px;">Demais seções da Ordem de Serviço</div>
                <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(200px,1fr)); gap:6px; margin-bottom:8px;">
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Recomendações</label><textarea id="gheCargoRecomendacoes-${i}" rows="2" style="${campoMini}">${escapeHTML(c.recomendacoes || '')}</textarea></div>
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Procedimentos em caso de acidentes</label><textarea id="gheCargoProcedimentosAcidentes-${i}" rows="2" style="${campoMini}">${escapeHTML(c.procedimentos_acidentes || '')}</textarea></div>
                    <div><label style="color:var(--text-light); font-size:10.5px; display:block;">Observações</label><textarea id="gheCargoObservacoes-${i}" rows="2" style="${campoMini}">${escapeHTML(c.observacoes || '')}</textarea></div>
                </div>
                <button class="db-clear-btn" onclick="salvarCargoAgentesEpi(${i})">💾 Salvar</button>
                <button class="db-clear-btn" style="color: var(--danger); border-color: var(--danger);" onclick="removerCargoGhe(${i})">🗑️ Remover cargo</button>
                <span id="gheCargoStatus-${i}" style="font-size:11px; color:var(--text-light); margin-left:8px;"></span>
            </td></tr>` : '';
            return `<tr style="border-top:1px solid var(--border); cursor:pointer;" onclick="toggleCargoGheDescricao(${i})">
                <td style="padding:4px 4px; color:var(--text-light);">${expandido ? '▾' : '▸'}</td>
                <td style="padding:4px 8px;">${escapeHTML(c.cargo || '') || '<span style="color:var(--text-light);">(sem cargo)</span>'}</td>
                <td style="padding:4px 8px;">${escapeHTML(c.funcao || '') || '<span style="color:var(--text-light);">(sem função)</span>'}</td>
                <td style="padding:4px 8px;">${escapeHTML(c.cbo || '')}</td>
                <td style="padding:4px 8px;">${escapeHTML(String(c.quantidade ?? ''))}</td>
            </tr>${linhaDetalhe}`;
        }).join('')}</tbody>
    </table>`;
}

async function salvarCargoAgentesEpi(i) {
    const g = allGheCatalogo.find(x => x.id === gheAtualGerenciado);
    if (!g || !Array.isArray(g.cargos) || !g.cargos[i]) return;
    const statusEl = document.getElementById(`gheCargoStatus-${i}`);
    const cargo = { ...g.cargos[i] };
    cargo.cargo = document.getElementById(`gheCargoCargo-${i}`).value.trim();
    cargo.funcao = document.getElementById(`gheCargoFuncao-${i}`).value.trim();
    cargo.cbo = document.getElementById(`gheCargoCbo-${i}`).value.trim();
    const quantidadeRaw = document.getElementById(`gheCargoQuantidade-${i}`).value.trim();
    cargo.quantidade = quantidadeRaw === '' ? '' : (Number.isNaN(Number(quantidadeRaw)) ? quantidadeRaw : Number(quantidadeRaw));
    cargo.descricao_atividade = document.getElementById(`gheCargoDescricaoAtividade-${i}`).value.trim();
    cargo.agentes = {
        fisico: document.getElementById(`gheCargoFisico-${i}`).value.trim(),
        quimico: document.getElementById(`gheCargoQuimico-${i}`).value.trim(),
        biologico: document.getElementById(`gheCargoBiologico-${i}`).value.trim(),
        ergonomico: document.getElementById(`gheCargoErgonomico-${i}`).value.trim(),
        acidentes: document.getElementById(`gheCargoAcidentes-${i}`).value.trim()
    };
    cargo.epis_necessarios = Array.isArray(gheCargoEpisForm[i]) ? gheCargoEpisForm[i].slice() : [];
    cargo.epcs_necessarios = Array.isArray(gheCargoEpcsForm[i]) ? gheCargoEpcsForm[i].slice() : [];
    cargo.recomendacoes = document.getElementById(`gheCargoRecomendacoes-${i}`).value.trim();
    cargo.procedimentos_acidentes = document.getElementById(`gheCargoProcedimentosAcidentes-${i}`).value.trim();
    cargo.observacoes = document.getElementById(`gheCargoObservacoes-${i}`).value.trim();
    const novoCargos = g.cargos.map((c, idx) => idx === i ? cargo : c);

    if (statusEl) { statusEl.textContent = 'Salvando...'; statusEl.style.color = 'var(--text-light)'; }
    try {
        // Upsert precisa da linha inteira - mesmo cuidado de salvarMapaRiscosGhe.
        await supabaseUpsert('ghe_catalogo', [{
            id: g.id,
            nome: g.nome,
            cargos: novoCargos,
            quantidade_oficial: g.quantidade_oficial,
            riscos: g.riscos || [],
            conclusoes: g.conclusoes || {},
            updated_at: new Date().toISOString()
        }]);
        g.cargos = novoCargos;
        // Reflete cargo/função/cbo/quantidade recém-salvos na linha colapsada da tabela.
        document.getElementById('gheCargosOficiais').innerHTML = renderGheCargosHtml(g);
        const statusReRenderizado = document.getElementById(`gheCargoStatus-${i}`);
        if (statusReRenderizado) { statusReRenderizado.textContent = '✅ Salvo.'; statusReRenderizado.style.color = 'var(--success)'; }
    } catch (err) {
        console.error('Erro ao salvar agentes/EPI do cargo:', err);
        if (statusEl) { statusEl.textContent = '❌ Falha: ' + err.message; statusEl.style.color = 'var(--danger)'; }
    }
}

// Remove um cargo do grupo (por índice) - único jeito de desfazer um "+ Adicionar cargo"
// feito sem querer ou um cargo de teste, já que antes não existia nenhuma forma de tirar
// um cargo da tela depois de criado. Só sai da tela DEPOIS do upsert confirmar - se der
// erro, a linha continua lá pra não passar a impressão de que a remoção funcionou.
async function removerCargoGhe(i) {
    const g = allGheCatalogo.find(x => x.id === gheAtualGerenciado);
    if (!g || !Array.isArray(g.cargos) || !g.cargos[i]) return;
    const cargo = g.cargos[i];
    const nomeExibicao = cargo.cargo || cargo.funcao || '(sem cargo)';
    if (!confirm(`Remover o cargo "${nomeExibicao}" deste grupo? Essa ação não pode ser desfeita.`)) return;

    const statusEl = document.getElementById(`gheCargoStatus-${i}`);
    if (statusEl) { statusEl.textContent = 'Removendo...'; statusEl.style.color = 'var(--text-light)'; }
    const novoCargos = g.cargos.filter((c, idx) => idx !== i);

    try {
        // Upsert precisa da linha inteira - mesmo cuidado de salvarCargoAgentesEpi.
        await supabaseUpsert('ghe_catalogo', [{
            id: g.id,
            nome: g.nome,
            cargos: novoCargos,
            quantidade_oficial: g.quantidade_oficial,
            riscos: g.riscos || [],
            conclusoes: g.conclusoes || {},
            updated_at: new Date().toISOString()
        }]);
        g.cargos = novoCargos;
        gheCargoExpandidoIdx = null;
        document.getElementById('gheCargosOficiais').innerHTML = renderGheCargosHtml(g);
        const gerenciarStatusEl = document.getElementById('gheGerenciarStatus');
        if (gerenciarStatusEl) { gerenciarStatusEl.textContent = '🗑️ Cargo removido.'; gerenciarStatusEl.style.color = 'var(--success)'; }
    } catch (err) {
        console.error('Erro ao remover cargo:', err);
        if (statusEl) { statusEl.textContent = '❌ Falha ao remover: ' + err.message; statusEl.style.color = 'var(--danger)'; }
    }
}

// ============================================
// RECOMENDAÇÕES POR CARGO (GHE) - revisão em lote, mesmo campo cargos[].recomendacoes
// já editável um a um em "Gerenciar GHE" (salvarCargoAgentesEpi acima), só que aqui
// achatado numa lista só com todos os cargos de todos os grupos, pra dar pra revisar
// sistematicamente em vez de abrir grupo por grupo. Não reescreve texto nenhum sozinho -
// só ajuda a achar rápido onde o texto está repetido (selo de duplicidade), quem edita
// e decide o texto novo é o usuário.
// ============================================

function todasRecomendacoesGhe() {
    const linhas = [];
    allGheCatalogo.forEach(g => {
        (Array.isArray(g.cargos) ? g.cargos : []).forEach((c, idx) => {
            linhas.push({ grupoId: g.id, grupoNome: g.nome, cargoIndex: idx, cargo: c.cargo || c.funcao || '(sem nome)', recomendacoes: c.recomendacoes || '' });
        });
    });

    const contagemPorTexto = {};
    linhas.forEach(l => {
        const norm = l.recomendacoes.trim().toLowerCase();
        if (!norm) return;
        contagemPorTexto[norm] = (contagemPorTexto[norm] || 0) + 1;
    });
    linhas.forEach(l => {
        const norm = l.recomendacoes.trim().toLowerCase();
        l.duplicados = norm && contagemPorTexto[norm] > 1 ? contagemPorTexto[norm] - 1 : 0;
    });
    return linhas;
}

function filterRecomendacoesGhe() {
    const termo = document.getElementById('recomendacoesSearchInput')?.value || '';
    const soDuplicados = document.getElementById('recomendacoesSoDuplicados')?.checked || false;
    renderRecomendacoesGheLista(termo, soDuplicados);
}

function renderRecomendacoesGheLista(termo = '', soDuplicados = false) {
    const container = document.getElementById('recomendacoesGheLista');
    const resumoEl = document.getElementById('recomendacoesResumo');
    if (!container) return;

    const todas = todasRecomendacoesGhe();
    const termoNorm = termo.trim().toLowerCase();
    const filtradas = todas.filter(l => {
        if (soDuplicados && l.duplicados === 0) return false;
        if (!termoNorm) return true;
        return (l.grupoNome || '').toLowerCase().includes(termoNorm) || (l.cargo || '').toLowerCase().includes(termoNorm) || (l.grupoId || '').toLowerCase().includes(termoNorm);
    });

    const totalDuplicados = todas.filter(l => l.duplicados > 0).length;
    if (resumoEl) resumoEl.textContent = `${todas.length} cargo(s) no total, ${totalDuplicados} com recomendação repetida de outro cargo. Mostrando ${filtradas.length}.`;

    if (filtradas.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum cargo encontrado com esse filtro.</div>';
        return;
    }

    container.innerHTML = filtradas.map(l => {
        const inputId = `recTextarea_${l.grupoId}_${l.cargoIndex}`;
        const statusId = `recStatus_${l.grupoId}_${l.cargoIndex}`;
        return `
        <div style="border:1px solid var(--border); border-radius:10px; padding:10px; margin-bottom:8px;">
            <div style="display:flex; justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap; margin-bottom:6px;">
                <div><b>${escapeHTML(l.grupoId)}</b> — ${escapeHTML(l.grupoNome)} · <span style="color:var(--text-light);">${escapeHTML(l.cargo)}</span></div>
                ${l.duplicados > 0 ? `<span style="padding:3px 10px; border-radius:12px; background:#fef1e0; color:#c2650a; font-weight:700; font-size:11px;">🔁 Igual a mais ${l.duplicados} cargo(s)</span>` : ''}
            </div>
            <textarea id="${inputId}" rows="2" style="width:100%; padding:8px; border:1px solid var(--border); border-radius:6px; font-size:12.5px; box-sizing:border-box; font-family:inherit;">${escapeHTML(l.recomendacoes)}</textarea>
            <div style="margin-top:6px; display:flex; align-items:center; gap:8px;">
                <button class="db-clear-btn" onclick="salvarRecomendacaoCargo('${escapeHTML(l.grupoId)}', ${l.cargoIndex})">💾 Salvar</button>
                <span id="${statusId}" style="font-size:11px; color:var(--text-light);"></span>
            </div>
        </div>`;
    }).join('');
}

async function salvarRecomendacaoCargo(grupoId, cargoIndex) {
    const g = allGheCatalogo.find(x => x.id === grupoId);
    if (!g || !Array.isArray(g.cargos) || !g.cargos[cargoIndex]) return;
    const inputId = `recTextarea_${grupoId}_${cargoIndex}`;
    const statusId = `recStatus_${grupoId}_${cargoIndex}`;
    const statusEl = document.getElementById(statusId);
    const novoTexto = document.getElementById(inputId).value.trim();

    const novoCargos = g.cargos.map((c, idx) => idx === cargoIndex ? { ...c, recomendacoes: novoTexto } : c);

    if (statusEl) { statusEl.textContent = 'Salvando...'; statusEl.style.color = 'var(--text-light)'; }
    try {
        // Upsert precisa da linha inteira do grupo - mesmo cuidado de salvarCargoAgentesEpi.
        await supabaseUpsert('ghe_catalogo', [{
            id: g.id,
            nome: g.nome,
            cargos: novoCargos,
            quantidade_oficial: g.quantidade_oficial,
            riscos: g.riscos || [],
            conclusoes: g.conclusoes || {},
            updated_at: new Date().toISOString()
        }]);
        g.cargos = novoCargos;
        if (statusEl) { statusEl.textContent = '✅ Salvo.'; statusEl.style.color = 'var(--success)'; }
        // Espera dar pra ver a confirmação antes de re-renderizar a lista (recalcula os
        // selos de duplicidade, que podem mudar pra essa e outras linhas).
        setTimeout(filterRecomendacoesGhe, 700);
    } catch (err) {
        console.error('Erro ao salvar recomendação do cargo:', err);
        if (statusEl) { statusEl.textContent = '❌ Falha: ' + err.message; statusEl.style.color = 'var(--danger)'; }
    }
}

function abrirGerenciarGhe(id) {
    const g = allGheCatalogo.find(x => x.id === id);
    if (!g) return;
    gheAtualGerenciado = id;
    document.getElementById('gheGerenciarTitulo').textContent = `🧪 ${g.id} — ${g.nome}`;
    document.getElementById('gheGerenciarStatus').textContent = '';
    document.getElementById('gheAddColabInput').value = '';
    document.getElementById('gheAddColabResults').innerHTML = '';

    gheCargoExpandidoIdx = null;
    document.getElementById('gheCargosOficiais').innerHTML = renderGheCargosHtml(g);
    document.getElementById('gheMapaRiscosView').innerHTML = renderGheMapaRiscosHtml(g);
    document.getElementById('gheMapaRiscosView').style.display = 'block';
    document.getElementById('gheMapaRiscosEdit').style.display = 'none';
    document.getElementById('gheBtnEditarRiscos').textContent = '✏️ Editar';

    document.getElementById('gheGerenciarCard').style.display = 'block';
    renderGheColabList();
    document.getElementById('gheGerenciarCard').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

// Troca entre visualização e edição do Mapa de Riscos + Conclusões do GHE aberto -
// permite ao técnico preencher manualmente os outros 26 grupos (o Grupo 27 foi
// pré-populado direto do laudo da ENGMED; os demais o laudo já concluiu "sem riscos
// significativos", mas a estrutura fica pronta pra quando um novo laudo trouxer dados).
let gheRiscosForm = [];

function rowRiscoGheVazio() {
    // probabilidade/severidade (1-5, vazios por padrão) alimentam nivelRiscoGhe() e
    // calculam gravidade/gravidade_label automaticamente (ver atualizarGravidadeCalculadaGhe)
    // - gravidade/gravidade_label continuam existindo como campos calculados, pra não
    // quebrar quem já lê eles hoje (KPIs, gráfico e lista de Riscos Altos/Muito Altos da
    // Matriz de Risco).
    return { tipo_agente: '', agente: '', probabilidade: '', severidade: '', gravidade: '', gravidade_label: '', fontes_geradoras: '', tipo_tempo_exposicao: '', descricao: '', danos_saude: '', sugestoes: '', epis_recomendados: '', epcs_recomendados: '', situacao_controle: '' };
}

function toggleEdicaoGheMapaRiscos() {
    const g = allGheCatalogo.find(x => x.id === gheAtualGerenciado);
    if (!g) return;
    const viewEl = document.getElementById('gheMapaRiscosView');
    const editEl = document.getElementById('gheMapaRiscosEdit');
    const editando = editEl.style.display !== 'none';
    if (editando) {
        editEl.style.display = 'none';
        viewEl.style.display = 'block';
        document.getElementById('gheBtnEditarRiscos').textContent = '✏️ Editar';
        return;
    }
    gheRiscosForm = Array.isArray(g.riscos) ? g.riscos.map(r => ({ ...r })) : [];
    renderRiscosGheForm();
    const c = g.conclusoes || {};
    document.getElementById('gheConclusaoGfipCodigo').value = c.gfip_codigo || '';
    document.getElementById('gheConclusaoGfipDescricao').value = c.gfip_descricao || '';
    document.getElementById('gheConclusaoPericulosidade').value = c.periculosidade || '';
    document.getElementById('gheConclusaoInsalubridade').value = c.insalubridade || '';
    document.getElementById('gheMapaRiscosStatus').textContent = '';
    viewEl.style.display = 'none';
    editEl.style.display = 'block';
    document.getElementById('gheBtnEditarRiscos').textContent = '✕ Cancelar';
}

function adicionarRiscoGheForm() {
    gheRiscosForm.push(rowRiscoGheVazio());
    renderRiscosGheForm();
}

function removerRiscoGheForm(i) {
    gheRiscosForm.splice(i, 1);
    renderRiscosGheForm();
}

function renderRiscosGheForm() {
    const container = document.getElementById('gheRiscosFormLista');
    if (!container) return;
    const campoEstilo = 'padding:6px; border:1px solid var(--border); border-radius:6px; font-size:11.5px; width:100%; box-sizing:border-box;';
    if (gheRiscosForm.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum risco cadastrado — clique em "➕ Adicionar Risco".</div>';
        return;
    }
    container.innerHTML = gheRiscosForm.map((r, i) => `
        <div style="border:1px solid var(--border); border-radius:10px; padding:10px; margin-bottom:10px; background:var(--bg);">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
                <b style="font-size:12px;">Risco ${i + 1}</b>
                <button onclick="removerRiscoGheForm(${i})" title="Remover" style="border:none; background:none; color:var(--danger); cursor:pointer; font-size:15px;">🗑️</button>
            </div>
            <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(150px,1fr)); gap:6px; margin-bottom:6px;">
                <input type="text" placeholder="Tipo de Agente (Físico/Químico/Biológico/Ergonômico/Acidentes)" value="${escapeHTML(r.tipo_agente)}" oninput="gheRiscosForm[${i}].tipo_agente=this.value" style="${campoEstilo}">
                <input type="text" placeholder="Agente" value="${escapeHTML(r.agente)}" oninput="gheRiscosForm[${i}].agente=this.value" style="${campoEstilo}">
            </div>
            <div style="display:grid; grid-template-columns: 70px 70px 1fr; gap:6px; align-items:end; margin-bottom:6px;">
                <div><label style="color:var(--text-light); font-size:10px; display:block;">Probabilidade</label>${selectProbSeverGhe(r.probabilidade, `gheRiscosForm[${i}].probabilidade=this.value; atualizarGravidadeCalculadaGhe(gheRiscosForm[${i}]); renderRiscosGheForm();`, APR_ANCORAS_P)}</div>
                <div><label style="color:var(--text-light); font-size:10px; display:block;">Severidade</label>${selectProbSeverGhe(r.severidade, `gheRiscosForm[${i}].severidade=this.value; atualizarGravidadeCalculadaGhe(gheRiscosForm[${i}]); renderRiscosGheForm();`, APR_ANCORAS_S)}</div>
                ${badgeGravidadeGhe(r)}
            </div>
            <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(150px,1fr)); gap:6px; margin-bottom:6px;">
                <input type="text" placeholder="Fontes Geradoras" value="${escapeHTML(r.fontes_geradoras)}" oninput="gheRiscosForm[${i}].fontes_geradoras=this.value" style="${campoEstilo}">
                <input type="text" placeholder="Tipo/Tempo de Exposição" value="${escapeHTML(r.tipo_tempo_exposicao)}" oninput="gheRiscosForm[${i}].tipo_tempo_exposicao=this.value" style="${campoEstilo}">
                <input type="text" placeholder="Situação de Controle" value="${escapeHTML(r.situacao_controle)}" oninput="gheRiscosForm[${i}].situacao_controle=this.value" style="${campoEstilo}">
            </div>
            <textarea placeholder="Descrição" oninput="gheRiscosForm[${i}].descricao=this.value" style="${campoEstilo} margin-bottom:6px;" rows="2">${escapeHTML(r.descricao)}</textarea>
            <textarea placeholder="Danos à Saúde" oninput="gheRiscosForm[${i}].danos_saude=this.value" style="${campoEstilo} margin-bottom:6px;" rows="1">${escapeHTML(r.danos_saude)}</textarea>
            <textarea placeholder="Sugestões / Medidas de Prevenção" oninput="gheRiscosForm[${i}].sugestoes=this.value" style="${campoEstilo} margin-bottom:6px;" rows="2">${escapeHTML(r.sugestoes)}</textarea>
            <div style="display:grid; grid-template-columns: 1fr 1fr; gap:6px;">
                <input type="text" placeholder="EPIs Recomendados" value="${escapeHTML(r.epis_recomendados)}" oninput="gheRiscosForm[${i}].epis_recomendados=this.value" style="${campoEstilo}">
                <input type="text" placeholder="EPCs Recomendados" value="${escapeHTML(r.epcs_recomendados)}" oninput="gheRiscosForm[${i}].epcs_recomendados=this.value" style="${campoEstilo}">
            </div>
        </div>`).join('');
}

async function salvarMapaRiscosGhe() {
    const statusEl = document.getElementById('gheMapaRiscosStatus');
    const g = allGheCatalogo.find(x => x.id === gheAtualGerenciado);
    if (!g) return;

    const riscosValidos = gheRiscosForm.filter(r => (r.agente || '').trim());
    const conclusoes = {
        gfip_codigo: document.getElementById('gheConclusaoGfipCodigo').value.trim() || null,
        gfip_descricao: document.getElementById('gheConclusaoGfipDescricao').value.trim() || null,
        periculosidade: document.getElementById('gheConclusaoPericulosidade').value.trim() || null,
        insalubridade: document.getElementById('gheConclusaoInsalubridade').value.trim() || null
    };

    statusEl.textContent = 'Salvando...';
    statusEl.style.color = 'var(--text-light)';
    try {
        // Upsert precisa da linha inteira - senão zera nome/cargos/quantidade_oficial
        // que não fazem parte deste formulário.
        await supabaseUpsert('ghe_catalogo', [{
            id: g.id,
            nome: g.nome,
            cargos: g.cargos,
            quantidade_oficial: g.quantidade_oficial,
            riscos: riscosValidos,
            conclusoes,
            updated_at: new Date().toISOString()
        }]);
        g.riscos = riscosValidos;
        g.conclusoes = conclusoes;
        statusEl.textContent = '✅ Mapa de riscos salvo.';
        statusEl.style.color = 'var(--success)';
        document.getElementById('gheMapaRiscosView').innerHTML = renderGheMapaRiscosHtml(g);
        toggleEdicaoGheMapaRiscos();
    } catch (err) {
        console.error('Erro ao salvar mapa de riscos do GHE:', err);
        statusEl.textContent = '❌ Falha ao salvar: ' + err.message;
        statusEl.style.color = 'var(--danger)';
    }
}

function fecharGerenciarGhe() {
    gheAtualGerenciado = null;
    const card = document.getElementById('gheGerenciarCard');
    if (card) card.style.display = 'none';
}

function renderGheColabList() {
    const container = document.getElementById('gheColabList');
    if (!container || !gheAtualGerenciado) return;
    const equipe = allEfetivo.filter(e => colaboradorEstaAtivo(e) && normalizarGhe(e.ghe) === gheAtualGerenciado)
        .sort((a, b) => (a.nome || '').localeCompare(b.nome || ''));

    if (equipe.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum colaborador classificado neste grupo ainda.</div>';
        return;
    }
    container.innerHTML = equipe.map(e => `
        <div class="db-list-item" style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
            <div>
                <div class="db-list-item-title">${escapeHTML(e.nome || '')}</div>
                <div class="db-list-item-sub">${escapeHTML(e.funcao || '')} — Matrícula ${escapeHTML(e.id)}</div>
            </div>
            <div style="display:flex; gap:6px; flex-shrink:0;">
                <button class="db-clear-btn" onclick="editarColaboradorDaEquipe('${escapeHTML(e.id)}')">✏️ Editar</button>
                <button class="db-clear-btn" style="color:var(--danger); border-color:var(--danger);" onclick="removerDoGhe('${escapeHTML(e.id)}')">Remover</button>
            </div>
        </div>`).join('');
}

function filterGheAddColab(query) {
    const container = document.getElementById('gheAddColabResults');
    const q = (query || '').toLowerCase().trim();
    if (q.length < 2) { container.innerHTML = ''; return; }

    const matches = allEfetivo.filter(e =>
        colaboradorEstaAtivo(e) && normalizarGhe(e.ghe) !== gheAtualGerenciado &&
        ((e.nome && e.nome.toLowerCase().includes(q)) || (e.id && e.id.toLowerCase().includes(q)))
    ).slice(0, 15);

    if (matches.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum colaborador encontrado</div>';
        return;
    }
    container.innerHTML = matches.map(e => `
        <div class="db-list-item" style="cursor:pointer;" onclick="adicionarAoGhe('${escapeHTML(e.id)}')">
            <div class="db-list-item-title">${escapeHTML(e.nome || '')}</div>
            <div class="db-list-item-sub">${escapeHTML(e.funcao || '')} — Matrícula ${escapeHTML(e.id)}${e.ghe ? ' — atualmente em ' + escapeHTML(e.ghe) : ' — sem GHE definido'}</div>
        </div>`).join('');
}

async function salvarGheColaborador(matricula, novoGhe) {
    const statusEl = document.getElementById('gheGerenciarStatus');
    const e = allEfetivo.find(x => x.id === matricula);
    if (!e) return;
    if (statusEl) { statusEl.textContent = 'Salvando...'; statusEl.style.color = 'var(--text-light)'; }
    try {
        await supabaseUpsert('colaboradores_efetivo', [{ id: matricula, ghe: novoGhe }]);
        e.ghe = novoGhe;
        if (statusEl) { statusEl.textContent = '✅ Atualizado.'; statusEl.style.color = 'var(--success)'; }
        renderGheColabList();
        renderGheLista();
    } catch (err) {
        console.error('Erro ao atualizar GHE do colaborador:', err);
        if (statusEl) { statusEl.textContent = '❌ Falha: ' + err.message; statusEl.style.color = 'var(--danger)'; }
    }
}

function adicionarAoGhe(matricula) {
    if (!gheAtualGerenciado) return;
    salvarGheColaborador(matricula, gheAtualGerenciado);
    document.getElementById('gheAddColabInput').value = '';
    document.getElementById('gheAddColabResults').innerHTML = '';
}

function removerDoGhe(matricula) {
    if (!confirm('Remover este colaborador do grupo? Ele fica sem GHE definido até ser adicionado a outro.')) return;
    salvarGheColaborador(matricula, null);
}

function popularGheCatalogoDatalist() {
    const el = document.getElementById('gheCatalogoList');
    if (!el) return;
    el.innerHTML = allGheCatalogo.slice().sort((a, b) => a.id.localeCompare(b.id))
        .map(g => `<option value="${escapeHTML(g.id)}">${escapeHTML(g.id)} — ${escapeHTML(g.nome)}</option>`).join('');
}

// Importa o Quadro Funcional (.xls/.xlsx real, exportado direto do sistema de GHE da
// empresa) via SheetJS no navegador. Mesma lógica de detecção de blocos validada antes
// contra o arquivo real no Node: uma linha onde a coluna B começa com "GRUPO " abre um
// novo grupo; as linhas seguintes com a coluna A preenchida (e diferente do cabeçalho
// "Cargo") são os cargos daquele grupo, até o próximo "GRUPO ".
async function importarQuadroFuncionalXLS() {
    const input = document.getElementById('gheFileInput');
    const statusEl = document.getElementById('gheImportStatus');
    if (!input.files || !input.files[0]) {
        statusEl.textContent = '❌ Selecione um arquivo .xls/.xlsx primeiro.';
        return;
    }

    statusEl.textContent = 'Lendo arquivo...';
    try {
        const file = input.files[0];
        const buffer = await file.arrayBuffer();
        const wb = XLSX.read(buffer, { type: 'array' });
        const sheet = wb.Sheets[wb.SheetNames[0]];
        const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });

        const grupos = [];
        let atual = null;
        rows.forEach(r => {
            const c0 = String(r[0] || '').trim();
            const c1 = String(r[1] || '').trim();
            const m = c1.match(/^GRUPO\s+(\d+)/i);
            if (m) {
                atual = { id: m[1].padStart(2, '0'), nome: c1, cargos: [] };
                grupos.push(atual);
            } else if (atual && c0 && c0 !== 'Cargo') {
                atual.cargos.push({ cargo: c0, funcao: String(r[1] || ''), cbo: String(r[3] || ''), quantidade: Number(r[4]) || 0 });
            }
        });

        if (grupos.length === 0) {
            statusEl.textContent = '❌ Nenhum grupo "GRUPO NN" encontrado nesse arquivo. Confirme se é o Quadro Funcional exportado do sistema de GHE.';
            return;
        }

        const linhas = grupos.map(g => ({
            id: g.id,
            nome: g.nome,
            cargos: g.cargos,
            quantidade_oficial: g.cargos.reduce((s, c) => s + c.quantidade, 0),
            updated_at: new Date().toISOString()
        }));

        statusEl.textContent = `Enviando ${linhas.length} grupo(s)...`;
        await supabaseUpsert('ghe_catalogo', linhas);

        const totalCargos = linhas.reduce((s, g) => s + g.cargos.length, 0);
        const totalPessoas = linhas.reduce((s, g) => s + g.quantidade_oficial, 0);
        statusEl.textContent = `✅ Importação concluída! ${linhas.length} grupo(s) de GHE e ${totalCargos} cargo(s) importados/atualizados, totalizando ${totalPessoas} pessoa(s) no quadro oficial.`;

        allGheCatalogo = await supabaseFetch('ghe_catalogo', '?select=*');
        popularGheCatalogoDatalist();
        if (document.getElementById('efetivoSubtabBtn-ghe')?.classList.contains('active')) renderGheLista();
    } catch (err) {
        console.error('Erro ao importar Quadro Funcional (GHE):', err);
        statusEl.textContent = '❌ Erro na importação: ' + err.message;
    }
}

// ============================================
// MATRIZ DE RISCO (metodologia AIHA, seção 16 do PGR) - painel 100% derivado de dado
// que já existe (ghe_catalogo.riscos[].gravidade/gravidade_label, atribuído durante o
// import original do PGR) + tabelas de referência estáticas transcritas das páginas
// 82-87/300. Sem tabela nova no Supabase, sem CRUD - é leitura/visualização.
// ============================================

let matrizRiscoLoaded = false;
let chartRiscoNivel = null;
let chartRiscoTipoAgente = null;

const NIVEIS_RISCO_ORDEM = ['Trivial', 'Baixo', 'Moderado', 'Alto', 'Muito Alto'];
const NIVEIS_RISCO_COR = { 'Trivial': '#6aa84f', 'Baixo': '#f1c232', 'Moderado': '#e69138', 'Alto': '#cc0000', 'Muito Alto': '#990000' };

// Mesma matriz 5×5 Probabilidade × Severidade do módulo de APR (nivelRiscoApr - valor =
// p × s, mesmas faixas 1-4/5-9/10-14/15-19/20-25), só que devolvendo os rótulos/cores que
// a Matriz de Risco do GHE já usa (NIVEIS_RISCO_ORDEM/NIVEIS_RISCO_COR acima) em vez dos
// rótulos do APR ('Aceitável / Baixo' etc, de outro módulo) - troca o campo de texto livre
// "Gravidade (rótulo...)" por uma classificação de verdade, calculada, não mais digitada
// à mão.
function nivelRiscoGhe(p, s) {
    const pNum = parseInt(p, 10);
    const sNum = parseInt(s, 10);
    if (!pNum || !sNum) return { valor: null, label: '', cor: '#888888' };
    const valor = pNum * sNum;
    const label = valor <= 4 ? 'Trivial' : valor <= 9 ? 'Baixo' : valor <= 14 ? 'Moderado' : valor <= 19 ? 'Alto' : 'Muito Alto';
    return { valor, label, cor: NIVEIS_RISCO_COR[label] };
}

// Select de Probabilidade/Severidade (1-5) com a âncora descritiva (APR_ANCORAS_P/S, mesma
// escala do APR) como tooltip de cada opção - mesmo padrão do selectPS local de
// renderRiscosAprForm, só que compartilhado entre os dois formulários de edição de riscos
// do GHE (gheRiscosForm e matrizEditForm) em vez de duplicado em cada um.
function selectProbSeverGhe(val, onchange, ancoras) {
    let opts = '<option value="">-</option>';
    for (let n = 1; n <= 5; n++) opts += `<option value="${n}" title="${escapeHTML(ancoras[n])}" ${String(val) === String(n) ? 'selected' : ''}>${n}</option>`;
    return `<select onchange="${onchange}" style="padding:6px; border:1px solid var(--border); border-radius:6px; font-size:11.5px; width:100%; box-sizing:border-box;">${opts}</select>`;
}

// Recalcula gravidade (número) e gravidade_label (texto) a partir de probabilidade ×
// severidade só quando a reclassificação fica completa (as duas preenchidas) - nesse
// momento o risco passa a usar o novo método de vez. Enquanto faltar uma das duas, deixa
// gravidade/gravidade_label como estavam (ex: rótulo antigo digitado à mão em risco
// importado do laudo original) - sem apagar ou adivinhar nada em massa.
function atualizarGravidadeCalculadaGhe(row) {
    const nivel = nivelRiscoGhe(row.probabilidade, row.severidade);
    if (nivel.valor !== null) {
        row.gravidade = nivel.valor;
        row.gravidade_label = nivel.label;
    }
}

// Badge só-leitura ao lado dos selects de P/S, mostrando o nível calculado ao vivo. Se
// probabilidade/severidade ainda não foram preenchidos os dois (risco antigo ainda não
// reclassificado, ou risco novo em branco), mostra o gravidade/gravidade_label que já
// estava salvo em vez de "—", pra não sumir com uma classificação antiga válida só porque
// os novos campos ainda não foram usados.
function badgeGravidadeGhe(row) {
    const nivel = nivelRiscoGhe(row.probabilidade, row.severidade);
    const valor = nivel.valor !== null ? nivel.valor : (row.gravidade || null);
    const label = nivel.valor !== null ? nivel.label : (row.gravidade_label || '');
    const cor = nivel.valor !== null ? nivel.cor : (NIVEIS_RISCO_COR[row.gravidade_label] || '#888888');
    return `<div title="Calculado a partir de Probabilidade × Severidade (mesma matriz do APR)" style="padding:6px 10px; border-radius:6px; background:${cor}22; color:${cor}; font-weight:700; font-size:11.5px; text-align:center;">
        ${valor !== null && valor !== '' ? 'Gravidade ' + valor : 'Gravidade —'}${label ? ' - ' + escapeHTML(label) : ''}
    </div>`;
}

function todosRiscosGhe() {
    const out = [];
    allGheCatalogo.forEach(g => {
        (Array.isArray(g.riscos) ? g.riscos : []).forEach(r => {
            out.push({ ...r, ghe_id: g.id, ghe_nome: g.nome });
        });
    });
    return out;
}

function renderMatrizRiscoPanel() {
    const riscos = todosRiscosGhe();

    document.getElementById('kpiRiscoTotal').textContent = riscos.length;
    const porNivel = {};
    NIVEIS_RISCO_ORDEM.forEach(n => { porNivel[n] = 0; });
    riscos.forEach(r => { if (porNivel[r.gravidade_label] !== undefined) porNivel[r.gravidade_label]++; });
    document.getElementById('kpiRiscoTrivial').textContent = porNivel['Trivial'];
    document.getElementById('kpiRiscoBaixo').textContent = porNivel['Baixo'];
    document.getElementById('kpiRiscoModerado').textContent = porNivel['Moderado'];
    document.getElementById('kpiRiscoAlto').textContent = porNivel['Alto'];
    document.getElementById('kpiRiscoMuitoAlto').textContent = porNivel['Muito Alto'];

    if (chartRiscoNivel) chartRiscoNivel.destroy();
    const ctxNivel = document.getElementById('chartRiscoNivel');
    if (ctxNivel) {
        chartRiscoNivel = new Chart(ctxNivel, {
            type: 'bar',
            data: {
                labels: NIVEIS_RISCO_ORDEM,
                datasets: [{ data: NIVEIS_RISCO_ORDEM.map(n => porNivel[n]), backgroundColor: NIVEIS_RISCO_ORDEM.map(n => NIVEIS_RISCO_COR[n]) }]
            },
            options: {
                responsive: true, maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                scales: { y: { beginAtZero: true, ticks: { precision: 0 } } }
            }
        });
    }

    const porTipoAgente = {};
    riscos.forEach(r => {
        const tipo = r.tipo_agente || 'Não classificado';
        porTipoAgente[tipo] = (porTipoAgente[tipo] || 0) + 1;
    });
    const tiposOrdenados = Object.entries(porTipoAgente).sort((a, b) => b[1] - a[1]);

    if (chartRiscoTipoAgente) chartRiscoTipoAgente.destroy();
    const ctxTipo = document.getElementById('chartRiscoTipoAgente');
    if (ctxTipo) {
        chartRiscoTipoAgente = new Chart(ctxTipo, {
            type: 'bar',
            data: {
                labels: tiposOrdenados.map(([tipo]) => tipo),
                datasets: [{ data: tiposOrdenados.map(([, n]) => n), backgroundColor: '#4a6fa5' }]
            },
            options: {
                indexAxis: 'y', responsive: true, maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                scales: { x: { beginAtZero: true, ticks: { precision: 0 } } }
            }
        });
    }

    const listaAltos = document.getElementById('listaRiscosAltos');
    if (listaAltos) {
        const altos = riscos.filter(r => r.gravidade_label === 'Alto' || r.gravidade_label === 'Muito Alto')
            .sort((a, b) => (b.gravidade || 0) - (a.gravidade || 0) || (a.ghe_id || '').localeCompare(b.ghe_id || ''));
        if (altos.length === 0) {
            listaAltos.innerHTML = '<div class="db-list-empty">Nenhum risco classificado como Alto ou Muito Alto nos grupos de GHE cadastrados.</div>';
        } else {
            listaAltos.innerHTML = altos.map(r => `
                <div class="db-list-item db-item-danger" style="cursor:pointer;" onclick="irParaGheDaMatriz('${escapeHTML(r.ghe_id)}')">
                    <div class="db-list-item-title">${escapeHTML(r.tipo_agente || '')} — ${escapeHTML(r.agente || '')}</div>
                    <div class="db-list-item-sub">${escapeHTML(r.ghe_id)} — ${escapeHTML(r.ghe_nome || '')} · <span style="font-weight:600; color:${NIVEIS_RISCO_COR[r.gravidade_label] || 'inherit'};">${escapeHTML(r.gravidade_label || '')}</span></div>
                </div>
            `).join('');
        }
    }
}

function irParaGheDaMatriz(gheId) {
    showDbPage('efetivo');
    showEfetivoSubtab('ghe');
    abrirGerenciarGhe(gheId);
}

// ============================================
// MATRIZ NR-6 (aba EPI) - mesma fonte de dado que a Matriz de Risco acima
// (ghe_catalogo.riscos[]), só que com foco em EPI recomendado por função e edição
// direta na própria aba (em vez de só leitura). Reaproveita renderGheMapaRiscosHtml
// (view) e o mesmo formato de linha de risco usado em "Gerenciar GHE"
// (Efetivo > GHE), mas com estado de edição próprio (matrizEdit*) pra não
// conflitar com gheAtualGerenciado/gheRiscosForm daquela outra tela.
// ============================================

let matrizEpiLoaded = false;
let matrizEditId = null;
let matrizEditForm = [];

function loadMatrizEpiData() {
    const jobs = [];
    if (allGheCatalogo.length === 0) jobs.push(supabaseFetch('ghe_catalogo', '?select=*').then(rows => { allGheCatalogo = rows; }));
    if (allEfetivo.length === 0) jobs.push(supabaseFetch('colaboradores_efetivo', '?select=*').then(rows => { allEfetivo = rows; }));
    Promise.all(jobs).then(() => {
        renderMatrizEpiCards();
        filterMatrizEpi(document.getElementById('mepiSearchInput')?.value || '');
    });
}

function setorDoGheNome(nome) {
    return String(nome || '').replace(/^GRUPO\s*\d+\s*-\s*/i, '').trim();
}

function funcoesDoGhe(g) {
    const nomes = (Array.isArray(g.cargos) ? g.cargos : []).map(c => c.funcao || c.cargo).filter(Boolean);
    return Array.from(new Set(nomes)).join(', ');
}

function renderMatrizEpiCards() {
    const wrap = document.getElementById('mepiCardsWrap');
    const resumo = document.getElementById('mepiResumo');
    if (!wrap) return;

    if (allGheCatalogo.length === 0) {
        wrap.innerHTML = '<div class="db-list-empty">Nenhum catálogo de GHE importado ainda. Envie o Quadro Funcional em Efetivo > Configurações.</div>';
        if (resumo) resumo.textContent = '';
        return;
    }

    const contagem = contagemAtualPorGhe();
    const grupos = allGheCatalogo.slice().sort((a, b) => a.id.localeCompare(b.id));
    const totalColab = Array.from(contagem.values()).reduce((s, v) => s + v, 0);
    if (resumo) resumo.textContent = `${grupos.length} grupo(s) homogêneo(s) de exposição · ${totalColab} colaborador(es) mapeado(s) no cadastro atual`;

    wrap.innerHTML = grupos.map(g => {
        const riscos = Array.isArray(g.riscos) ? g.riscos : [];
        const atual = contagem.get(g.id) || 0;
        const setor = setorDoGheNome(g.nome);
        const funcoes = funcoesDoGhe(g);
        const buscaTxt = [setor, funcoes, ...riscos.map(r => r.agente || '')].join(' ').toLowerCase();
        const editando = matrizEditId === g.id;

        return `<div class="mepi-card" id="mepiCard-${escapeHTML(g.id)}" data-search="${escapeHTML(buscaTxt)}">
            <div class="mepi-card-head">
                <span class="mepi-ghe">GHE ${escapeHTML(g.id)}</span>
                <div class="mepi-head-text">
                    <div class="mepi-setor">${escapeHTML(setor)}</div>
                    <div class="mepi-funcoes">${escapeHTML(funcoes)}</div>
                </div>
                <span class="mepi-n" style="color:${atual > 0 ? 'var(--text)' : 'var(--text-light)'}">${atual > 0 ? atual + ' colab.' : 'sem colab. ativo'}</span>
            </div>
            <div id="mepiView-${escapeHTML(g.id)}">${renderGheMapaRiscosHtml(g)}</div>
            <div class="mepi-footer" style="border-top:1px dashed var(--border); padding-top:8px; margin-top:8px;">
                <button class="db-clear-btn" onclick="toggleMatrizEdit('${escapeHTML(g.id)}')">${editando ? '✕ Cancelar' : '✏️ Editar riscos'}</button>
            </div>
            ${editando ? renderMatrizEditBlock(g) : ''}
        </div>`;
    }).join('');
}

function renderMatrizEditBlock(g) {
    return `<div style="margin-top:10px; border-top:1px solid var(--border); padding-top:10px;">
        <div id="mepiEditFields-${escapeHTML(g.id)}"></div>
        <button class="db-clear-btn" onclick="adicionarMatrizRisco()">➕ Adicionar Risco</button>
        <button class="db-clear-btn" style="margin-left:6px;" onclick="salvarMatrizRiscos()">💾 Salvar</button>
        <span id="mepiEditStatus-${escapeHTML(g.id)}" style="font-size:11px; color:var(--text-light); margin-left:8px;"></span>
    </div>`;
}

function toggleMatrizEdit(id) {
    if (matrizEditId === id) {
        matrizEditId = null;
        matrizEditForm = [];
        renderMatrizEpiCards();
        filterMatrizEpi(document.getElementById('mepiSearchInput')?.value || '');
        return;
    }
    const g = allGheCatalogo.find(x => x.id === id);
    if (!g) return;
    matrizEditId = id;
    matrizEditForm = Array.isArray(g.riscos) ? g.riscos.map(r => ({ ...r })) : [];
    renderMatrizEpiCards();
    filterMatrizEpi(document.getElementById('mepiSearchInput')?.value || '');
    renderMatrizEditFields();
    document.getElementById('mepiCard-' + id)?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function adicionarMatrizRisco() {
    matrizEditForm.push(rowRiscoGheVazio());
    renderMatrizEditFields();
}

function removerMatrizRisco(i) {
    matrizEditForm.splice(i, 1);
    renderMatrizEditFields();
}

function renderMatrizEditFields() {
    if (!matrizEditId) return;
    const container = document.getElementById('mepiEditFields-' + matrizEditId);
    if (!container) return;
    const campoEstilo = 'padding:6px; border:1px solid var(--border); border-radius:6px; font-size:11.5px; width:100%; box-sizing:border-box;';
    if (matrizEditForm.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum risco cadastrado — clique em "➕ Adicionar Risco".</div>';
        return;
    }
    container.innerHTML = matrizEditForm.map((r, i) => `
        <div style="border:1px solid var(--border); border-radius:10px; padding:10px; margin-bottom:10px; background:var(--bg);">
            <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">
                <b style="font-size:12px;">Risco ${i + 1}</b>
                <button onclick="removerMatrizRisco(${i})" title="Remover" style="border:none; background:none; color:var(--danger); cursor:pointer; font-size:15px;">🗑️</button>
            </div>
            <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(150px,1fr)); gap:6px; margin-bottom:6px;">
                <input type="text" placeholder="Tipo de Agente (Físico/Químico/Biológico/Ergonômico/Acidentes)" value="${escapeHTML(r.tipo_agente)}" oninput="matrizEditForm[${i}].tipo_agente=this.value" style="${campoEstilo}">
                <input type="text" placeholder="Agente" value="${escapeHTML(r.agente)}" oninput="matrizEditForm[${i}].agente=this.value" style="${campoEstilo}">
            </div>
            <div style="display:grid; grid-template-columns: 70px 70px 1fr; gap:6px; align-items:end; margin-bottom:6px;">
                <div><label style="color:var(--text-light); font-size:10px; display:block;">Probabilidade</label>${selectProbSeverGhe(r.probabilidade, `matrizEditForm[${i}].probabilidade=this.value; atualizarGravidadeCalculadaGhe(matrizEditForm[${i}]); renderMatrizEditFields();`, APR_ANCORAS_P)}</div>
                <div><label style="color:var(--text-light); font-size:10px; display:block;">Severidade</label>${selectProbSeverGhe(r.severidade, `matrizEditForm[${i}].severidade=this.value; atualizarGravidadeCalculadaGhe(matrizEditForm[${i}]); renderMatrizEditFields();`, APR_ANCORAS_S)}</div>
                ${badgeGravidadeGhe(r)}
            </div>
            <div style="display:grid; grid-template-columns: repeat(auto-fit, minmax(150px,1fr)); gap:6px; margin-bottom:6px;">
                <input type="text" placeholder="Fontes Geradoras" value="${escapeHTML(r.fontes_geradoras)}" oninput="matrizEditForm[${i}].fontes_geradoras=this.value" style="${campoEstilo}">
                <input type="text" placeholder="Tipo/Tempo de Exposição" value="${escapeHTML(r.tipo_tempo_exposicao)}" oninput="matrizEditForm[${i}].tipo_tempo_exposicao=this.value" style="${campoEstilo}">
                <input type="text" placeholder="Situação de Controle" value="${escapeHTML(r.situacao_controle)}" oninput="matrizEditForm[${i}].situacao_controle=this.value" style="${campoEstilo}">
            </div>
            <textarea placeholder="Descrição" oninput="matrizEditForm[${i}].descricao=this.value" style="${campoEstilo} margin-bottom:6px;" rows="2">${escapeHTML(r.descricao)}</textarea>
            <textarea placeholder="Danos à Saúde" oninput="matrizEditForm[${i}].danos_saude=this.value" style="${campoEstilo} margin-bottom:6px;" rows="1">${escapeHTML(r.danos_saude)}</textarea>
            <textarea placeholder="Sugestões / Medidas de Prevenção" oninput="matrizEditForm[${i}].sugestoes=this.value" style="${campoEstilo} margin-bottom:6px;" rows="2">${escapeHTML(r.sugestoes)}</textarea>
            <div style="display:grid; grid-template-columns: 1fr 1fr; gap:6px;">
                <input type="text" placeholder="EPIs Recomendados" value="${escapeHTML(r.epis_recomendados)}" oninput="matrizEditForm[${i}].epis_recomendados=this.value" style="${campoEstilo}">
                <input type="text" placeholder="EPCs Recomendados" value="${escapeHTML(r.epcs_recomendados)}" oninput="matrizEditForm[${i}].epcs_recomendados=this.value" style="${campoEstilo}">
            </div>
        </div>`).join('');
}

async function salvarMatrizRiscos() {
    const g = allGheCatalogo.find(x => x.id === matrizEditId);
    if (!g) return;
    const statusEl = document.getElementById('mepiEditStatus-' + matrizEditId);
    const riscosValidos = matrizEditForm.filter(r => (r.agente || '').trim());

    if (statusEl) { statusEl.textContent = 'Salvando...'; statusEl.style.color = 'var(--text-light)'; }
    try {
        // Upsert precisa da linha inteira - mesmo cuidado de salvarMapaRiscosGhe.
        await supabaseUpsert('ghe_catalogo', [{
            id: g.id,
            nome: g.nome,
            cargos: g.cargos,
            quantidade_oficial: g.quantidade_oficial,
            riscos: riscosValidos,
            conclusoes: g.conclusoes || {},
            updated_at: new Date().toISOString()
        }]);
        g.riscos = riscosValidos;
        matrizEditId = null;
        matrizEditForm = [];
        renderMatrizEpiCards();
        filterMatrizEpi(document.getElementById('mepiSearchInput')?.value || '');
    } catch (err) {
        console.error('Erro ao salvar riscos da Matriz NR-6:', err);
        if (statusEl) { statusEl.textContent = '❌ Falha ao salvar: ' + err.message; statusEl.style.color = 'var(--danger)'; }
    }
}

// ============================================
// EFETIVO - busca de colaborador (ativo/inativo, admissão/demissão, tempo de casa,
// aniversário e situação de treinamentos), a pedido do cliente.
// ============================================

// Resumo geral da lista de colaboradores (visão geral rápida, mesmo espírito do
// catalogoResumo): total, quantos ativos x inativos.
function renderEfetivoResumo() {
    const el = document.getElementById('efetivoResumo');
    if (!el) return;
    const total = allEfetivo.length;
    const ativos = allEfetivo.filter(e => e.dt_admissao && !e.dt_demissao).length;
    el.textContent = total === 0 ? '' : `${total} colaborador(es) cadastrado(s) — ${ativos} ativo(s), ${total - ativos} inativo(s)`;
}

function limparBuscaEfetivo() {
    const input = document.getElementById('efetivoSearchInput');
    input.value = '';
    filterEfetivoColaboradores('');
    input.focus();
}

// ---- Gerar PDF de Colaboradores (Ativos/Demitidos/Completo, colunas escolhidas) ----
// Mesmo padrão de blob+<a>+window.print() de todo documento gerado no sistema - "PDF" é
// o navegador imprimindo/salvando essa página HTML, não uma lib de PDF.
const EFETIVO_PDF_COLUNAS = [
    { id: 'matricula', label: 'Matrícula', get: e => e.id },
    { id: 'nome', label: 'Nome', get: e => e.nome },
    { id: 'status', label: 'Status', get: e => e.status },
    { id: 'funcao', label: 'Função', get: e => e.funcao },
    { id: 'setor', label: 'Setor', get: e => e.setor },
    { id: 'responsavel', label: 'Responsável/Frente', get: e => e.responsavel },
    { id: 'ghe', label: 'GHE', get: e => e.ghe },
    { id: 'cpf', label: 'CPF', get: e => e.cpf },
    { id: 'dt_admissao', label: 'Admissão', get: e => formatSimpleDate(e.dt_admissao) },
    { id: 'dt_demissao', label: 'Demissão', get: e => formatSimpleDate(e.dt_demissao) },
    { id: 'dt_nascimento', label: 'Nascimento', get: e => formatSimpleDate(e.dt_nascimento) },
    { id: 'cidade', label: 'Cidade', get: e => e.cidade },
    { id: 'estado', label: 'UF', get: e => e.estado },
    { id: 'estabilidade', label: 'Estabilidade', get: e => e.estabilidade },
    { id: 'sexo', label: 'Sexo', get: e => e.sexo }
];
const EFETIVO_PDF_COLUNAS_PADRAO = new Set(['matricula', 'nome', 'status', 'funcao', 'setor']);
let efetivoPdfStatusFiltro = 'ativos';

function toggleFormPdfEfetivo() {
    const card = document.getElementById('efetivoPdfCard');
    const abrindo = card.style.display === 'none';
    card.style.display = abrindo ? 'block' : 'none';
    if (abrindo && document.getElementById('efetivoPdfColunas').children.length === 0) {
        document.getElementById('efetivoPdfColunas').innerHTML = EFETIVO_PDF_COLUNAS.map(c => `
            <label style="display:flex; align-items:center; gap:6px; cursor:pointer;">
                <input type="checkbox" class="efetivoPdfColunaCheckbox" value="${c.id}" ${EFETIVO_PDF_COLUNAS_PADRAO.has(c.id) ? 'checked' : ''} style="width:15px; height:15px;">
                <span>${escapeHTML(c.label)}</span>
            </label>`).join('');
    }
}

function setEfetivoPdfStatus(status) {
    efetivoPdfStatusFiltro = status;
    ['ativos', 'demitidos', 'completo'].forEach(s => document.getElementById(`efPdfStatusBtn-${s}`)?.classList.toggle('active', s === status));
}

function gerarPdfEfetivo() {
    const statusEl = document.getElementById('efetivoPdfStatus');
    const colunasMarcadas = Array.from(document.querySelectorAll('.efetivoPdfColunaCheckbox:checked')).map(cb => cb.value);
    if (colunasMarcadas.length === 0) {
        statusEl.textContent = '❌ Selecione pelo menos uma coluna.';
        statusEl.style.color = 'var(--danger)';
        return;
    }
    const colunas = EFETIVO_PDF_COLUNAS.filter(c => colunasMarcadas.includes(c.id));

    let lista = allEfetivo.slice();
    let filtroLabel = 'Completo (Ativos + Demitidos)';
    if (efetivoPdfStatusFiltro === 'ativos') { lista = lista.filter(colaboradorEstaAtivo); filtroLabel = 'Ativos'; }
    else if (efetivoPdfStatusFiltro === 'demitidos') { lista = lista.filter(e => !colaboradorEstaAtivo(e)); filtroLabel = 'Demitidos/Inativos'; }
    lista.sort((a, b) => (a.nome || '').localeCompare(b.nome || ''));

    if (lista.length === 0) {
        statusEl.textContent = 'Nenhum colaborador encontrado para esse filtro.';
        statusEl.style.color = 'var(--text-light)';
        return;
    }

    const agora = new Date();
    const html = `<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="UTF-8">
<title>Lista de Colaboradores - ${escapeHTML(filtroLabel)}</title>
<style>
    @page { size: landscape; margin: 12mm; }
    body { font-family: Arial, Helvetica, sans-serif; font-size: 10px; color: #111; margin: 20px; }
    .cabecalho { display:flex; align-items:center; justify-content:space-between; border-bottom:2px solid #000; padding-bottom:8px; margin-bottom:6px; gap:10px; }
    .cabecalho img { max-height:40px; }
    .cabecalho .titulo { font-weight:700; font-size:16px; text-align:center; flex:1; }
    .info-geracao { font-size:10.5px; color:#444; margin-bottom:12px; }
    table { width:100%; border-collapse:collapse; font-size:9.5px; }
    th, td { border:1px solid #999; padding:4px 6px; text-align:left; }
    th { background:#e5e5e5; }
    tbody tr:nth-child(even) { background:#f7f7f7; }
    .no-print { text-align:center; margin:16px 0; }
    .no-print button { padding:10px 24px; font-size:14px; font-weight:600; cursor:pointer; border-radius:8px; border:none; background:#4f46e5; color:#fff; }
    @media print { .no-print { display:none; } body { margin:0; } thead { display: table-header-group; } }
</style></head>
<body>
    <div class="no-print"><button onclick="window.print()">🖨️ Imprimir / Salvar como PDF</button></div>
    <div class="cabecalho">
        <img src="${LOGO_COP_BASE64}" alt="COP">
        <div class="titulo">LISTA DE COLABORADORES — ${escapeHTML(filtroLabel.toUpperCase())}</div>
        <div style="width:40px;"></div>
    </div>
    <div class="info-geracao">${escapeHTML(EMPRESA_INFO.razaoSocial)} — Gerado em ${formatSimpleDate(agora.toISOString().slice(0, 10))} às ${agora.toLocaleTimeString('pt-BR')} — ${lista.length} colaborador(es)</div>
    <table>
        <thead><tr>${colunas.map(c => `<th>${escapeHTML(c.label)}</th>`).join('')}</tr></thead>
        <tbody>${lista.map(e => `<tr>${colunas.map(c => `<td>${escapeHTML(c.get(e) || '')}</td>`).join('')}</tr>`).join('')}</tbody>
    </table>
</body></html>`;

    abrirDocumentoBlob(html);
    statusEl.textContent = `✅ PDF gerado com ${lista.length} colaborador(es).`;
    statusEl.style.color = 'var(--success)';
}

function filterEfetivoColaboradores(query) {
    const container = document.getElementById('efetivoSearchResults');
    const detail = document.getElementById('efetivoColabDetail');
    const q = (query || '').toLowerCase().trim();

    // Sem busca, mostra todo mundo (visão geral) em vez de ficar vazio - a busca só
    // entra pra estreitar a lista, mesmo padrão já usado no Catálogo de Treinamentos.
    const base = q.length < 2
        ? allEfetivo
        : allEfetivo.filter(e => (e.nome && e.nome.toLowerCase().includes(q)) || (e.id && e.id.toLowerCase().includes(q)));
    const matches = base.slice().sort((a, b) => (a.nome || '').localeCompare(b.nome || ''));

    if (matches.length === 0) {
        container.innerHTML = q.length < 2
            ? '<div class="db-list-empty">Nenhum colaborador cadastrado ainda</div>'
            : `<div class="db-list-empty">Nenhum colaborador encontrado para "${escapeHTML(query)}"</div>`;
        return;
    }

    container.innerHTML = matches.map(e => {
        const ativo = e.dt_admissao && !e.dt_demissao;
        const cls = ativo ? '' : 'db-item-danger';
        return `<div class="db-list-item ${cls}" style="cursor:pointer;" onclick="mostrarDetalheColaborador('${escapeHTML(e.id)}')">
            <div class="db-list-item-title">${escapeHTML(e.nome || '(sem nome)')}</div>
            <div class="db-list-item-sub">Matrícula ${escapeHTML(e.id)} — ${escapeHTML(e.funcao || '')}${ativo ? '' : ' (Inativo)'}</div>
        </div>`;
    }).join('');
}

function calcularIdade(dataNascimento, hoje) {
    let idade = hoje.getFullYear() - dataNascimento.getFullYear();
    const aindaNaoFezAniversario = (hoje.getMonth() < dataNascimento.getMonth()) ||
        (hoje.getMonth() === dataNascimento.getMonth() && hoje.getDate() < dataNascimento.getDate());
    if (aindaNaoFezAniversario) idade--;
    return idade;
}

function diasProximoAniversario(dataNascimento, hoje) {
    let prox = new Date(hoje.getFullYear(), dataNascimento.getMonth(), dataNascimento.getDate());
    if (prox < hoje) prox = new Date(hoje.getFullYear() + 1, dataNascimento.getMonth(), dataNascimento.getDate());
    return Math.ceil((prox.getTime() - hoje.getTime()) / (1000 * 60 * 60 * 24));
}

let colabTreinamentosDetalhe = [];
let colabTreinBadgeAberto = null;

// Mostra/esconde a lista de treinamentos por trás de um badge (vencido/vencendo/
// válido/sem validade) clicado no card de detalhe do colaborador.
function toggleTreinamentosBadge(status) {
    const container = document.getElementById('colabTreinDetalheLista');
    if (!container) return;

    if (colabTreinBadgeAberto === status) {
        container.style.display = 'none';
        colabTreinBadgeAberto = null;
        return;
    }
    colabTreinBadgeAberto = status;

    const itens = colabTreinamentosDetalhe.filter(t => t.status === status).sort((a, b) => {
        if (a.diff === null || b.diff === null) return (a.treinamento_nome || '').localeCompare(b.treinamento_nome || '');
        return a.diff - b.diff;
    });

    if (itens.length === 0) {
        container.innerHTML = '<div class="db-list-empty">Nenhum treinamento nessa categoria</div>';
        container.style.display = 'block';
        return;
    }

    container.innerHTML = itens.map(t => {
        let statusTxt;
        if (t.status === 'vencido') statusTxt = `Venceu há ${Math.abs(t.diff)} dia(s)`;
        else if (t.status === 'vencendo') statusTxt = t.diff === 0 ? 'Vence hoje' : `Vence em ${t.diff} dia(s)`;
        else if (t.status === 'valido') statusTxt = `Válido (${t.diff} dias restantes)`;
        else statusTxt = 'Sem validade / não recicla';
        return `
            <div class="db-list-item" style="font-size: 12.5px;">
                <div class="db-list-item-title">${escapeHTML(t.treinamento_nome || t.treinamento_cod || '')}</div>
                <div class="db-list-item-sub">${statusTxt} — Última realização: ${t.data_treinamento ? formatSimpleDate(t.data_treinamento) : '—'}${t.data_proxima_reciclagem ? ' • Válido até: ' + formatSimpleDate(t.data_proxima_reciclagem) : ''}</div>
            </div>`;
    }).join('');
    container.style.display = 'block';
}

function mostrarDetalheColaborador(matricula) {
    const e = allEfetivo.find(x => x.id === matricula);
    if (!e) return;
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);

    const admissao = e.dt_admissao ? parseLocalDate(e.dt_admissao) : null;
    const demissao = e.dt_demissao ? parseLocalDate(e.dt_demissao) : null;
    const ativo = admissao && !demissao;

    const statusBadge = ativo
        ? `<span style="font-size: 11px; padding: 3px 10px; border-radius: 8px; background: #d1fae5; color: #047857; font-weight: 700;">🟢 ATIVO</span>`
        : `<span style="font-size: 11px; padding: 3px 10px; border-radius: 8px; background: #fee2e2; color: #b91c1c; font-weight: 700;">🔴 ${escapeHTML(e.status || 'INATIVO')}</span>`;

    let tempoCasaTxt = '—';
    if (admissao) {
        const fimRef = demissao || hoje;
        const totalMeses = Math.floor((fimRef.getTime() - admissao.getTime()) / (1000 * 60 * 60 * 24 * 30.44));
        const anos = Math.floor(totalMeses / 12);
        const mesesResto = totalMeses % 12;
        tempoCasaTxt = anos > 0 ? `${anos} ano(s) e ${mesesResto} mês(es)` : `${mesesResto} mês(es)`;
        if (demissao) tempoCasaTxt += ' (até a demissão)';
    }

    let aniversarioTxt = '—';
    if (e.dt_nascimento) {
        const dn = parseLocalDate(e.dt_nascimento);
        const idade = calcularIdade(dn, hoje);
        const diffDias = diasProximoAniversario(dn, hoje);
        aniversarioTxt = `${dn.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long' })} (${idade} anos)`;
        if (diffDias === 0) aniversarioTxt += ' — 🎂 é hoje!';
        else if (diffDias <= 30) aniversarioTxt += ` — 🎂 em ${diffDias} dia(s)`;
    }

    // Situação de treinamentos, se já carregada (loadEfetivoData sempre garante o carregamento).
    // Nem todo treinamento tem validade (DDS pontuais têm meses_validade nulo) - esses
    // entram no bucket "sem validade" pra não sumir da contagem total. Os badges são
    // clicáveis (toggleTreinamentosBadge) pra mostrar quais treinamentos exatamente caem
    // em cada categoria - antes só dava pra ver a contagem, sem saber quais.
    let treinHtml = '';
    const regs = allTreinamentosStatus.filter(t => t.matricula === matricula);
    colabTreinamentosDetalhe = [];
    colabTreinBadgeAberto = null;
    if (regs.length > 0) {
        let vencidos = 0, vencendo = 0, validos = 0, semValidade = 0;
        regs.forEach(t => {
            let diff = null, status;
            if (!t.data_proxima_reciclagem) {
                status = 'sem_validade';
                semValidade++;
            } else {
                const d = parseLocalDate(t.data_proxima_reciclagem);
                diff = Math.ceil((d.getTime() - hoje.getTime()) / (1000 * 60 * 60 * 24));
                if (diff < 0) { status = 'vencido'; vencidos++; }
                else if (diff <= 30) { status = 'vencendo'; vencendo++; }
                else { status = 'valido'; validos++; }
            }
            colabTreinamentosDetalhe.push({ ...t, diff, status });
        });
        treinHtml = `
            <div style="margin-top: 14px; padding-top: 14px; border-top: 1px dashed var(--border);">
                <div style="font-size: 11px; color: var(--text-light); font-weight: 700; text-transform: uppercase; margin-bottom: 6px;">Situação de Treinamentos (${regs.length}) <span style="font-weight: 400; text-transform: none;">— clique numa categoria pra ver quais</span></div>
                <div style="display: flex; gap: 8px; flex-wrap: wrap;">
                    <button style="font-size: 11px; padding: 4px 10px; border-radius: 6px; background: #fee2e2; color: #b91c1c; font-weight: 600; border: 1px solid #fecaca; cursor: pointer;" onclick="toggleTreinamentosBadge('vencido')">🔴 ${vencidos} vencido(s)</button>
                    <button style="font-size: 11px; padding: 4px 10px; border-radius: 6px; background: #fef3c7; color: #92400e; font-weight: 600; border: 1px solid #fde68a; cursor: pointer;" onclick="toggleTreinamentosBadge('vencendo')">🟡 ${vencendo} vencendo</button>
                    <button style="font-size: 11px; padding: 4px 10px; border-radius: 6px; background: #d1fae5; color: #047857; font-weight: 600; border: 1px solid #a7f3d0; cursor: pointer;" onclick="toggleTreinamentosBadge('valido')">🟢 ${validos} válido(s)</button>
                    <button style="font-size: 11px; padding: 4px 10px; border-radius: 6px; background: #e0e7ff; color: #3730a3; font-weight: 600; border: 1px solid #c7d2fe; cursor: pointer;" onclick="toggleTreinamentosBadge('sem_validade')">🔵 ${semValidade} sem validade</button>
                </div>
                <div id="colabTreinDetalheLista" class="db-list" style="display:none; margin-top: 10px; max-height: 280px;"></div>
            </div>`;
    }

    const detail = document.getElementById('efetivoColabDetail');
    detail.innerHTML = `
        <div style="display:flex; justify-content: space-between; align-items: flex-start; flex-wrap: wrap; gap: 8px;">
            <div>
                <div style="font-size: 16px; font-weight: 700;">${escapeHTML(e.nome || '')}</div>
                <div style="font-size: 12px; color: var(--text-light); margin-top: 2px;">${escapeHTML(e.funcao || '')}${e.setor ? ' — ' + escapeHTML(e.setor) : ''}</div>
            </div>
            <div style="display:flex; gap:8px; align-items:center;">
                ${statusBadge}
                <button class="db-clear-btn" onclick="abrirFormEfetivo('${escapeHTML(matricula)}')">✏️ Editar</button>
            </div>
        </div>
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 10px; margin-top: 14px; font-size: 12.5px;">
            <div><strong>Matrícula:</strong> ${escapeHTML(e.id)}</div>
            <div><strong>Admissão:</strong> ${admissao ? formatSimpleDate(e.dt_admissao) : '—'}</div>
            <div><strong>Demissão:</strong> ${demissao ? formatSimpleDate(e.dt_demissao) : '—'}</div>
            <div><strong>Tempo de casa:</strong> ${tempoCasaTxt}</div>
            <div><strong>Aniversário:</strong> ${aniversarioTxt}</div>
            <div><strong>Responsável:</strong> ${escapeHTML(e.responsavel || '—')}</div>
            <div><strong>Cidade/UF:</strong> ${escapeHTML(e.cidade || '—')}${e.estado ? '/' + escapeHTML(e.estado) : ''}</div>
            <div><strong>Estabilidade:</strong> ${escapeHTML(e.estabilidade || '—')}</div>
            <div><strong>GHE:</strong> ${escapeHTML(e.ghe || '—')}</div>
            <div><strong>CPF:</strong> ${escapeHTML(e.cpf || '—')}</div>
            <div><strong>Uniforme:</strong> Calça ${escapeHTML(e.calca || '—')} / Camisa ${escapeHTML(e.camisa || '—')} / Bota ${escapeHTML(e.bota || '—')}</div>
            <div><strong>Sexo:</strong> ${escapeHTML(e.sexo || '—')}</div>
        </div>
        ${treinHtml}
    `;
    detail.style.display = 'block';
    detail.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

// Cadastro/edição manual de colaborador, complementando a importação em massa por CSV -
// depois que a base estiver preenchida, o dia a dia (admissão/demissão/correção pontual)
// não precisa mais passar por planilha.
function abrirFormEfetivo(matricula) {
    const form = document.getElementById('efetivoFormCard');
    const title = document.getElementById('efetivoFormTitle');
    const matriculaInput = document.getElementById('efForm_matricula');
    document.getElementById('efetivoFormStatus').textContent = '';

    if (matricula) {
        const e = allEfetivo.find(x => x.id === matricula);
        if (!e) return;
        title.textContent = '✏️ Editar Colaborador';
        matriculaInput.value = e.id || '';
        matriculaInput.readOnly = true;
        matriculaInput.style.background = 'var(--bg)';
        document.getElementById('efForm_nome').value = e.nome || '';
        document.getElementById('efForm_status').value = e.status || 'ATIVO';
        document.getElementById('efForm_funcao').value = e.funcao || '';
        document.getElementById('efForm_setor').value = e.setor || '';
        document.getElementById('efForm_responsavel').value = e.responsavel || '';
        document.getElementById('efForm_dt_admissao').value = e.dt_admissao || '';
        document.getElementById('efForm_dt_demissao').value = e.dt_demissao || '';
        document.getElementById('efForm_dt_nascimento').value = e.dt_nascimento || '';
        document.getElementById('efForm_cpf').value = e.cpf || '';
        document.getElementById('efForm_cidade').value = e.cidade || '';
        document.getElementById('efForm_estado').value = e.estado || '';
        document.getElementById('efForm_estabilidade').value = e.estabilidade || 'NÃO';
        document.getElementById('efForm_ghe').value = e.ghe || '';
        document.getElementById('efForm_sexo').value = e.sexo || 'MASCULINO';
        document.getElementById('efForm_calca').value = e.calca || '';
        document.getElementById('efForm_camisa').value = e.camisa || '';
        document.getElementById('efForm_bota').value = e.bota || '';
    } else {
        title.textContent = '👤 Novo Colaborador';
        ['matricula', 'nome', 'funcao', 'setor', 'responsavel', 'dt_admissao', 'dt_demissao', 'dt_nascimento', 'cpf', 'cidade', 'estado', 'ghe', 'calca', 'camisa', 'bota']
            .forEach(f => { const el = document.getElementById('efForm_' + f); if (el) el.value = ''; });
        document.getElementById('efForm_status').value = 'ATIVO';
        document.getElementById('efForm_estabilidade').value = 'NÃO';
        document.getElementById('efForm_sexo').value = 'MASCULINO';
        matriculaInput.readOnly = false;
        matriculaInput.style.background = '';
    }

    form.style.display = 'block';
    form.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function fecharFormEfetivo() {
    document.getElementById('efetivoFormCard').style.display = 'none';
}

async function salvarColaboradorEfetivo() {
    const statusEl = document.getElementById('efetivoFormStatus');
    const matricula = document.getElementById('efForm_matricula').value.trim();
    const nome = document.getElementById('efForm_nome').value.trim();

    if (!matricula || !nome) {
        statusEl.textContent = '❌ Matrícula e nome são obrigatórios.';
        statusEl.style.color = 'var(--danger)';
        return;
    }

    const row = {
        id: matricula,
        status: document.getElementById('efForm_status').value,
        nome,
        funcao: document.getElementById('efForm_funcao').value.trim(),
        setor: document.getElementById('efForm_setor').value.trim(),
        responsavel: document.getElementById('efForm_responsavel').value.trim(),
        dt_admissao: document.getElementById('efForm_dt_admissao').value || null,
        dt_demissao: document.getElementById('efForm_dt_demissao').value || null,
        dt_nascimento: document.getElementById('efForm_dt_nascimento').value || null,
        cpf: document.getElementById('efForm_cpf').value.trim(),
        cidade: document.getElementById('efForm_cidade').value.trim(),
        estado: document.getElementById('efForm_estado').value.trim(),
        estabilidade: document.getElementById('efForm_estabilidade').value,
        ghe: document.getElementById('efForm_ghe').value.trim(),
        sexo: document.getElementById('efForm_sexo').value,
        calca: document.getElementById('efForm_calca').value.trim(),
        camisa: document.getElementById('efForm_camisa').value.trim(),
        bota: document.getElementById('efForm_bota').value.trim()
    };

    statusEl.textContent = 'Salvando...';
    statusEl.style.color = 'var(--text-light)';
    try {
        await supabaseUpsert('colaboradores_efetivo', [row]);
        const idx = allEfetivo.findIndex(e => e.id === matricula);
        if (idx >= 0) allEfetivo[idx] = { ...allEfetivo[idx], ...row };
        else allEfetivo.push(row);

        statusEl.textContent = '✅ Salvo com sucesso.';
        statusEl.style.color = 'var(--success)';
        renderEfetivoPanel();
        renderEfetivoResumo();
        filterEfetivoColaboradores(document.getElementById('efetivoSearchInput').value);
        setTimeout(() => {
            fecharFormEfetivo();
            mostrarDetalheColaborador(matricula);
        }, 600);
    } catch (err) {
        console.error('Erro ao salvar colaborador:', err);
        statusEl.textContent = '❌ Falha ao salvar: ' + err.message;
        statusEl.style.color = 'var(--danger)';
    }
}

function headcountAsOf(dateEnd) {
    return allEfetivo.filter(e => {
        if (!e.dt_admissao) return false;
        if (parseLocalDate(e.dt_admissao) > dateEnd) return false;
        if (!e.dt_demissao) return true;
        return parseLocalDate(e.dt_demissao) > dateEnd;
    }).length;
}

// HHT normativo (Efetivo do mês × 220h) - denominador padrão de exposição usado tanto
// no índice HHT/Efetivo quanto nas taxas de frequência/gravidade (módulo de
// Acidentabilidade). Extraído aqui pra ser reutilizável fora do render do Efetivo.
function hht220DoMes(ano, mesIndex0) {
    const fimMes = new Date(ano, mesIndex0 + 1, 0);
    return headcountAsOf(fimMes) * 220;
}

// HHT de DDS num intervalo/mês - mesma lógica de filtro por data que hhtDoMes já usa,
// só que somando carga_horaria de allDdsRealizados em vez de allTreinamentosRealizados.
function ddsHorasNoPeriodo(inicio, fim) {
    return allDdsRealizados
        .filter(r => { if (!r.data_dds) return false; const d = parseLocalDate(r.data_dds); return d >= inicio && d <= fim; })
        .reduce((sum, r) => sum + (parseFloat(r.carga_horaria) || 0), 0);
}

function ddsHorasDoMes(ano, mesIndex0) {
    const ini = new Date(ano, mesIndex0, 1);
    const fim = new Date(ano, mesIndex0 + 1, 0);
    return ddsHorasNoPeriodo(ini, fim);
}

// HHT GERAL do mês = treinamento formal + DDS - mesma conta que a planilha oficial
// (QUADRO_DE_TREINAMENTOS) já faz na mão (confirmado batendo o Quadro de Julho/26: HHT
// geral = treinamento + integração + DDS, convertendo DDS a 10min/tema/dia ÷ 60). Somar o
// DDS aqui, na fonte única usada pelo Índice HHT/Efetivo da aba Efetivo, é o que faz esse
// índice do sistema bater com o que a empresa já reporta oficialmente - antes ficava
// sempre abaixo por nunca contar o DDS.
function hhtDoMes(ano, mesIndex0) {
    const ini = new Date(ano, mesIndex0, 1);
    const fim = new Date(ano, mesIndex0 + 1, 0);
    const hhtTreinamento = allTreinamentosRealizados
        .filter(r => { if (!r.data_treinamento) return false; const d = parseLocalDate(r.data_treinamento); return d >= ini && d <= fim; })
        .reduce((sum, r) => sum + (parseFloat(r.carga_horaria) || 0), 0);
    return hhtTreinamento + ddsHorasDoMes(ano, mesIndex0);
}

let efetivoFiltroAno = '';
let efetivoFiltroMes = '';

// Popula o select de anos com base nos dados reais (admissão/demissão), não uma lista
// fixa - "dinâmico" a pedido do usuário, então acompanha a base automaticamente.
function popularFiltroAnoEfetivo() {
    const anos = new Set([new Date().getFullYear()]);
    allEfetivo.forEach(e => {
        if (e.dt_admissao) anos.add(parseLocalDate(e.dt_admissao).getFullYear());
        if (e.dt_demissao) anos.add(parseLocalDate(e.dt_demissao).getFullYear());
    });
    popularSelectAnos('efetivoFiltroAno', anos);
}

function onEfetivoFiltroChange() {
    efetivoFiltroAno = document.getElementById('efetivoFiltroAno').value;
    efetivoFiltroMes = document.getElementById('efetivoFiltroMes').value;
    renderEfetivoPanel();
}

function limparFiltroEfetivo() {
    document.getElementById('efetivoFiltroAno').value = '';
    document.getElementById('efetivoFiltroMes').value = '';
    efetivoFiltroAno = '';
    efetivoFiltroMes = '';
    renderEfetivoPanel();
}

function renderEfetivoPanel() {
    if (allEfetivo.length === 0) return;
    popularFiltroAnoEfetivo();

    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);

    // Mês sem ano selecionado não tem sentido sozinho (mês de qual ano?), então só
    // entra em vigor quando o ano também está selecionado.
    const anoSel = efetivoFiltroAno ? parseInt(efetivoFiltroAno, 10) : null;
    const mesSel = (anoSel !== null && efetivoFiltroMes !== '') ? parseInt(efetivoFiltroMes, 10) : null;
    const nomesMeses = ['Janeiro', 'Fevereiro', 'Março', 'Abril', 'Maio', 'Junho', 'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'];

    // periodoInicio/periodoFim definem a janela usada nos KPIs de admissões/demissões/
    // turnover; dataRef é o "hoje" usado pro efetivo atual e tempo de casa - sem filtro,
    // os dois continuam exatamente como antes (hoje / últimos 12 meses).
    let periodoInicio, periodoFim, dataRef, tituloPeriodo;
    if (anoSel !== null && mesSel !== null) {
        periodoInicio = new Date(anoSel, mesSel, 1);
        const fimMesCalc = new Date(anoSel, mesSel + 1, 0);
        periodoFim = fimMesCalc > hoje ? hoje : fimMesCalc;
        dataRef = periodoFim;
        tituloPeriodo = `${nomesMeses[mesSel]} de ${anoSel}`;
    } else if (anoSel !== null) {
        periodoInicio = new Date(anoSel, 0, 1);
        const fimAnoCalc = new Date(anoSel, 11, 31);
        periodoFim = fimAnoCalc > hoje ? hoje : fimAnoCalc;
        dataRef = periodoFim;
        tituloPeriodo = `Ano de ${anoSel}`;
    } else {
        periodoInicio = new Date(hoje.getFullYear(), hoje.getMonth() - 11, 1);
        periodoFim = hoje;
        dataRef = hoje;
        tituloPeriodo = 'Últimos 12 meses';
    }
    const periodoTituloEl = document.getElementById('efetivoPeriodoTitulo');
    if (periodoTituloEl) periodoTituloEl.textContent = tituloPeriodo;

    const efetivoAtual = headcountAsOf(dataRef);
    document.getElementById('kpiEfetivoAtual').textContent = efetivoAtual;

    const admissoesPeriodo = allEfetivo.filter(e => e.dt_admissao && parseLocalDate(e.dt_admissao) >= periodoInicio && parseLocalDate(e.dt_admissao) <= periodoFim).length;
    const demissoesPeriodo = allEfetivo.filter(e => e.dt_demissao && parseLocalDate(e.dt_demissao) >= periodoInicio && parseLocalDate(e.dt_demissao) <= periodoFim).length;
    document.getElementById('kpiEfetivoAdmissoes').textContent = admissoesPeriodo;
    document.getElementById('kpiEfetivoDemissoes').textContent = demissoesPeriodo;

    const efetivoInicioPeriodo = headcountAsOf(new Date(periodoInicio.getFullYear(), periodoInicio.getMonth(), 0));
    const efetivoMedioPeriodo = (efetivoAtual + efetivoInicioPeriodo) / 2;
    const turnover = efetivoMedioPeriodo > 0 ? (demissoesPeriodo / efetivoMedioPeriodo * 100) : 0;
    document.getElementById('kpiEfetivoTurnover').textContent = turnover.toFixed(1) + '%';

    const ativosNaData = allEfetivo.filter(e => e.dt_admissao && parseLocalDate(e.dt_admissao) <= dataRef && (!e.dt_demissao || parseLocalDate(e.dt_demissao) > dataRef));
    let tempoCasaTotalMeses = 0;
    ativosNaData.forEach(e => {
        const adm = parseLocalDate(e.dt_admissao);
        tempoCasaTotalMeses += (dataRef.getTime() - adm.getTime()) / (1000 * 60 * 60 * 24 * 30.44);
    });
    document.getElementById('kpiEfetivoTempoCasa').textContent = ativosNaData.length > 0 ? Math.round(tempoCasaTotalMeses / ativosNaData.length) : 0;

    // Aniversariantes do mês: usa sempre o mês corrente REAL (hoje), não o dataRef do
    // filtro de período - é um indicador de RH pra saber quem faz aniversário agora,
    // não um corte histórico, então não deve mudar quando o usuário filtra "Ano 2024"
    // ou qualquer outro período no seletor acima.
    const mesCorrente = hoje.getMonth();
    const ativosHojeReal = allEfetivo.filter(e => e.dt_admissao && parseLocalDate(e.dt_admissao) <= hoje && (!e.dt_demissao || parseLocalDate(e.dt_demissao) > hoje));
    const aniversariantesDoMes = ativosHojeReal
        .filter(e => e.dt_nascimento && parseLocalDate(e.dt_nascimento).getMonth() === mesCorrente)
        .map(e => {
            const nasc = parseLocalDate(e.dt_nascimento);
            return { nome: e.nome || e.id, funcao: e.funcao, dia: nasc.getDate(), idadeQueCompleta: hoje.getFullYear() - nasc.getFullYear() };
        })
        .sort((a, b) => a.dia - b.dia);

    const tituloAnivEl = document.getElementById('tituloAniversariantesMes');
    if (tituloAnivEl) tituloAnivEl.textContent = nomesMeses[mesCorrente];

    const listAnivEl = document.getElementById('listAniversariantesMes');
    if (listAnivEl) {
        if (aniversariantesDoMes.length === 0) {
            listAnivEl.innerHTML = 'Nenhum aniversariante ativo este mês.';
        } else {
            listAnivEl.innerHTML = aniversariantesDoMes.map(a => {
                const dataFmt = `${String(a.dia).padStart(2, '0')}/${String(mesCorrente + 1).padStart(2, '0')}`;
                const destaque = a.dia === hoje.getDate() ? ' 🎉 <strong>hoje!</strong>' : '';
                return `${dataFmt} — ${escapeHTML(a.nome)} (${escapeHTML(a.funcao || 'sem função')}, completa ${a.idadeQueCompleta} anos)${destaque}`;
            }).join('<br>');
        }
    }

    // Evolução mensal: com um ano selecionado, mostra só os 12 meses daquele ano (ou até
    // o mês atual, se for o ano corrente); sem filtro, mantém o histórico completo de
    // sempre (da primeira admissão registrada até hoje).
    const meses = [], admissoesPorMes = [], demissoesPorMes = [], efetivoPorMes = [], indicePorMes = [];
    // hht220PorMes: "Horas Homens Trabalhadas" no sentido normativo (efetivo do mês × 220h
    // mês-padrão) - metrica DIFERENTE do HHT de treinamento usado no índice acima; a
    // planilha do cliente rastreia as duas separadamente (confirmado batendo o valor de
    // jul/2024: efetivo 35 × 220 = 7700, exatamente o que a planilha mostra).
    // admArcoverdePorMes/admSertaniaPorMes: admissões do mês por município da ADA (Área
    // Diretamente Afetada) - as duas únicas cidades que contam pra esse indicador.
    const hht220PorMes = [], admArcoverdePorMes = [], admSertaniaPorMes = [];
    let cursor, limite;
    if (anoSel !== null) {
        cursor = new Date(anoSel, 0, 1);
        limite = anoSel === hoje.getFullYear() ? new Date(hoje.getFullYear(), hoje.getMonth(), 1) : new Date(anoSel, 11, 1);
    } else {
        const datasAdmissao = allEfetivo.filter(e => e.dt_admissao).map(e => parseLocalDate(e.dt_admissao));
        const primeiraData = datasAdmissao.length > 0 ? new Date(Math.min(...datasAdmissao.map(d => d.getTime()))) : hoje;
        cursor = new Date(primeiraData.getFullYear(), primeiraData.getMonth(), 1);
        limite = new Date(hoje.getFullYear(), hoje.getMonth(), 1);
    }
    while (cursor <= limite) {
        const ano = cursor.getFullYear(), mes = cursor.getMonth();
        const inicioMes = new Date(ano, mes, 1);
        const fimMes = new Date(ano, mes + 1, 0);
        meses.push(cursor.toLocaleDateString('pt-BR', { month: 'short', year: '2-digit' }));
        const admDoMes = allEfetivo.filter(e => e.dt_admissao && parseLocalDate(e.dt_admissao) >= inicioMes && parseLocalDate(e.dt_admissao) <= fimMes);
        const dem = allEfetivo.filter(e => e.dt_demissao && parseLocalDate(e.dt_demissao) >= inicioMes && parseLocalDate(e.dt_demissao) <= fimMes).length;
        const eft = headcountAsOf(fimMes);
        const hht = hhtDoMes(ano, mes);
        admissoesPorMes.push(admDoMes.length);
        demissoesPorMes.push(dem);
        efetivoPorMes.push(eft);
        indicePorMes.push(eft > 0 ? Math.round((hht / eft) * 100) : 0);
        hht220PorMes.push(eft * 220);
        admArcoverdePorMes.push(admDoMes.filter(e => (e.cidade || '').toUpperCase().trim() === 'ARCOVERDE').length);
        admSertaniaPorMes.push(admDoMes.filter(e => (e.cidade || '').toUpperCase().trim() === 'SERTÂNIA').length);
        cursor = new Date(ano, mes + 1, 1);
    }

    if (typeof Chart === 'undefined') return;
    if (chartInstances.efetivoEvolucao) chartInstances.efetivoEvolucao.destroy();
    if (chartInstances.efetivoIndice) chartInstances.efetivoIndice.destroy();
    if (chartInstances.efetivoSetor) chartInstances.efetivoSetor.destroy();
    if (chartInstances.efetivoFuncao) chartInstances.efetivoFuncao.destroy();
    if (chartInstances.efetivoHHT220) chartInstances.efetivoHHT220.destroy();
    if (chartInstances.efetivoSexo) chartInstances.efetivoSexo.destroy();
    if (chartInstances.efetivoFaixaEtaria) chartInstances.efetivoFaixaEtaria.destroy();
    if (chartInstances.efetivoAniversariantes) chartInstances.efetivoAniversariantes.destroy();
    if (chartInstances.adaAtual) chartInstances.adaAtual.destroy();
    if (chartInstances.adaAdmissoes) chartInstances.adaAdmissoes.destroy();

    chartInstances.efetivoEvolucao = new Chart(document.getElementById('chartEfetivoEvolucao'), {
        type: 'line',
        data: {
            labels: meses,
            datasets: [
                { label: 'Efetivo', data: efetivoPorMes, borderColor: '#4f46e5', backgroundColor: 'rgba(79,70,229,0.08)', fill: true, tension: 0.25, yAxisID: 'y' },
                { label: 'Admissões', data: admissoesPorMes, borderColor: '#10b981', backgroundColor: 'transparent', tension: 0.25, yAxisID: 'y1' },
                { label: 'Demissões', data: demissoesPorMes, borderColor: '#ef4444', backgroundColor: 'transparent', tension: 0.25, yAxisID: 'y1' }
            ]
        },
        options: {
            responsive: true, maintainAspectRatio: false,
            scales: {
                y: { position: 'left', beginAtZero: true, title: { display: true, text: 'Efetivo' } },
                y1: { position: 'right', beginAtZero: true, grid: { drawOnChartArea: false }, title: { display: true, text: 'Adm/Dem' } }
            }
        }
    });

    chartInstances.efetivoIndice = new Chart(document.getElementById('chartEfetivoIndice'), {
        type: 'bar',
        data: { labels: meses, datasets: [{ label: 'Índice HHT/Efetivo × 100', data: indicePorMes, backgroundColor: '#818cf8', borderRadius: 6 }] },
        options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } }
    });

    const setorCounts = {};
    ativosNaData.forEach(e => { const s = e.setor || 'Sem setor'; setorCounts[s] = (setorCounts[s] || 0) + 1; });
    const setorSorted = Object.entries(setorCounts).sort((a, b) => b[1] - a[1]);
    const efetivoSetorLabels = setorSorted.map(s => wrapChartLabel(s[0]));
    ajustarAlturaBarrasHorizontais('chartEfetivoSetor', efetivoSetorLabels);
    chartInstances.efetivoSetor = new Chart(document.getElementById('chartEfetivoSetor'), {
        type: 'bar',
        data: { labels: efetivoSetorLabels, datasets: [{ label: 'Efetivo', data: setorSorted.map(s => s[1]), backgroundColor: '#10b981', borderRadius: 6 }] },
        options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { beginAtZero: true, ticks: { stepSize: 1 } }, y: { ticks: { autoSkip: false } } } }
    });

    const funcaoCounts = {};
    ativosNaData.forEach(e => { const f = e.funcao || 'Sem função'; funcaoCounts[f] = (funcaoCounts[f] || 0) + 1; });
    const funcaoSorted = Object.entries(funcaoCounts).sort((a, b) => b[1] - a[1]).slice(0, 10);
    const efetivoFuncaoLabels = funcaoSorted.map(f => wrapChartLabel(f[0]));
    ajustarAlturaBarrasHorizontais('chartEfetivoFuncao', efetivoFuncaoLabels);
    chartInstances.efetivoFuncao = new Chart(document.getElementById('chartEfetivoFuncao'), {
        type: 'bar',
        data: { labels: efetivoFuncaoLabels, datasets: [{ label: 'Efetivo', data: funcaoSorted.map(f => f[1]), backgroundColor: '#f59e0b', borderRadius: 6 }] },
        options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { beginAtZero: true, ticks: { stepSize: 1 } }, y: { ticks: { autoSkip: false } } } }
    });

    // Horas Homens Trabalhadas normativo (efetivo × 220h/mês) - indicador de exposição
    // usado pra taxas de frequência/gravidade, diferente do HHT de treinamento acima.
    chartInstances.efetivoHHT220 = new Chart(document.getElementById('chartEfetivoHHT220'), {
        type: 'bar',
        data: { labels: meses, datasets: [{ label: 'HHT (Efetivo × 220)', data: hht220PorMes, backgroundColor: '#4f46e5', borderRadius: 6 }] },
        options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true } } }
    });

    const sexoCounts = { MASCULINO: 0, FEMININO: 0 };
    ativosNaData.forEach(e => {
        const s = (e.sexo || '').toUpperCase().trim();
        if (sexoCounts[s] !== undefined) sexoCounts[s]++;
    });
    chartInstances.efetivoSexo = new Chart(document.getElementById('chartEfetivoSexo'), {
        type: 'doughnut',
        data: {
            labels: ['Masculino', 'Feminino'],
            datasets: [{ data: [sexoCounts.MASCULINO, sexoCounts.FEMININO], backgroundColor: ['#4f46e5', '#ec4899'], borderWidth: 2, borderColor: '#fff' }]
        },
        options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom' } }, cutout: '55%' }
    });

    // Faixa etária: idade calculada em dataRef (não "hoje" fixo, pra ficar consistente
    // com os outros gráficos "Efetivo Atual" quando um ano/mês específico está filtrado).
    // Colaboradores sem dt_nascimento cadastrada entram em "Não informado" em vez de
    // serem descartados silenciosamente da contagem.
    const FAIXAS_ETARIAS = [
        { label: '< 25 anos', min: 0, max: 24 },
        { label: '25-34 anos', min: 25, max: 34 },
        { label: '35-44 anos', min: 35, max: 44 },
        { label: '45-54 anos', min: 45, max: 54 },
        { label: '55+ anos', min: 55, max: Infinity }
    ];
    const faixaEtariaCounts = FAIXAS_ETARIAS.map(() => 0);
    let semNascimentoCount = 0;
    ativosNaData.forEach(e => {
        if (!e.dt_nascimento) { semNascimentoCount++; return; }
        const nasc = parseLocalDate(e.dt_nascimento);
        let idade = dataRef.getFullYear() - nasc.getFullYear();
        const aniversarioAindaNaoChegou = (dataRef.getMonth() < nasc.getMonth()) ||
            (dataRef.getMonth() === nasc.getMonth() && dataRef.getDate() < nasc.getDate());
        if (aniversarioAindaNaoChegou) idade--;
        const idx = FAIXAS_ETARIAS.findIndex(f => idade >= f.min && idade <= f.max);
        if (idx >= 0) faixaEtariaCounts[idx]++;
    });
    const faixaEtariaLabels = FAIXAS_ETARIAS.map(f => f.label);
    const faixaEtariaData = faixaEtariaCounts.slice();
    if (semNascimentoCount > 0) { faixaEtariaLabels.push('Não informado'); faixaEtariaData.push(semNascimentoCount); }
    chartInstances.efetivoFaixaEtaria = new Chart(document.getElementById('chartEfetivoFaixaEtaria'), {
        type: 'bar',
        data: { labels: faixaEtariaLabels, datasets: [{ label: 'Efetivo', data: faixaEtariaData, backgroundColor: '#0ea5e9', borderRadius: 6 }] },
        options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { beginAtZero: true, ticks: { stepSize: 1 } } } }
    });

    // Gráfico de aniversariantes: só os dias do mês corrente que realmente têm alguém
    // fazendo aniversário (não os 31 dias em branco) - mesma convenção de "só plota
    // categorias que existem" usada nos outros gráficos de barra deste arquivo. O
    // tooltip mostra o(s) nome(s) daquele dia, já que a lista abaixo do gráfico
    // (listAniversariantesMes, preenchida mais acima) cobre o detalhe completo.
    const diasComAniversario = [...new Set(aniversariantesDoMes.map(a => a.dia))].sort((a, b) => a - b);
    const contagemPorDia = diasComAniversario.map(d => aniversariantesDoMes.filter(a => a.dia === d).length);
    const nomesPorDia = diasComAniversario.map(d => aniversariantesDoMes.filter(a => a.dia === d).map(a => a.nome).join(', '));
    chartInstances.efetivoAniversariantes = new Chart(document.getElementById('chartEfetivoAniversariantes'), {
        type: 'bar',
        data: { labels: diasComAniversario.map(d => `dia ${d}`), datasets: [{ label: 'Aniversariantes', data: contagemPorDia, backgroundColor: '#ec4899', borderRadius: 6 }] },
        options: {
            responsive: true, maintainAspectRatio: false,
            plugins: { legend: { display: false }, tooltip: { callbacks: { label: (ctx) => nomesPorDia[ctx.dataIndex] } } },
            scales: { y: { beginAtZero: true, ticks: { stepSize: 1 } } }
        }
    });

    // ADA (Área Diretamente Afetada): as duas únicas cidades que contam pro indicador -
    // todo o resto do efetivo (outras cidades de origem) entra em "Outros".
    const adaCounts = { ARCOVERDE: 0, 'SERTÂNIA': 0, OUTROS: 0 };
    ativosNaData.forEach(e => {
        const c = (e.cidade || '').toUpperCase().trim();
        if (c === 'ARCOVERDE') adaCounts.ARCOVERDE++;
        else if (c === 'SERTÂNIA') adaCounts['SERTÂNIA']++;
        else adaCounts.OUTROS++;
    });
    chartInstances.adaAtual = new Chart(document.getElementById('chartAdaAtual'), {
        type: 'doughnut',
        data: {
            labels: ['Arcoverde', 'Sertânia', 'Outros'],
            datasets: [{ data: [adaCounts.ARCOVERDE, adaCounts['SERTÂNIA'], adaCounts.OUTROS], backgroundColor: ['#10b981', '#f59e0b', '#94a3b8'], borderWidth: 2, borderColor: '#fff' }]
        },
        options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'bottom' } }, cutout: '55%' }
    });

    const totalAda = ativosNaData.length;
    const resumoEl = document.getElementById('adaResumo');
    if (resumoEl) {
        const pct = n => totalAda > 0 ? ((n / totalAda) * 100).toFixed(1) : '0.0';
        resumoEl.innerHTML = `Arcoverde: <strong>${adaCounts.ARCOVERDE}</strong> (${pct(adaCounts.ARCOVERDE)}%) — Sertânia: <strong>${adaCounts['SERTÂNIA']}</strong> (${pct(adaCounts['SERTÂNIA'])}%) — Outros: <strong>${adaCounts.OUTROS}</strong> (${pct(adaCounts.OUTROS)}%)`;
    }

    chartInstances.adaAdmissoes = new Chart(document.getElementById('chartAdaAdmissoes'), {
        type: 'bar',
        data: {
            labels: meses,
            datasets: [
                { label: 'Arcoverde', data: admArcoverdePorMes, backgroundColor: '#10b981', borderRadius: 4 },
                { label: 'Sertânia', data: admSertaniaPorMes, backgroundColor: '#f59e0b', borderRadius: 4 }
            ]
        },
        options: { responsive: true, maintainAspectRatio: false, scales: { y: { beginAtZero: true, ticks: { stepSize: 1 } } } }
    });
}

async function importarEfetivoCSV() {
    const input = document.getElementById('efetivoFileInput');
    const statusEl = document.getElementById('efetivoImportStatus');
    if (!input.files || !input.files[0]) {
        statusEl.textContent = '❌ Selecione um arquivo CSV primeiro.';
        return;
    }

    statusEl.textContent = 'Lendo arquivo...';
    try {
        const file = input.files[0];
        const rawText = await file.text();
        const text = rawText.replace(/^﻿/, '');
        const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
        if (lines.length < 2) {
            statusEl.textContent = '❌ Arquivo vazio ou sem linhas de dados.';
            return;
        }

        const headers = lines[0].split(';').map(h => h.trim().toUpperCase());
        const idx = {};
        headers.forEach((h, i) => { idx[h] = i; });
        function col(parts, name) {
            const i = idx[name.toUpperCase()];
            return i !== undefined ? (parts[i] || '').trim() : '';
        }

        const efetivoMap = new Map();
        let puladas = 0;
        for (let li = 1; li < lines.length; li++) {
            const parts = lines[li].split(';');
            const matricula = col(parts, 'MATRICULA').toUpperCase();
            const nome = col(parts, 'NOME');
            if (!matricula || !nome) { puladas++; continue; }

            efetivoMap.set(matricula, {
                id: matricula,
                status: col(parts, 'STATUS'),
                cpf: col(parts, 'CPF'),
                nome,
                funcao: col(parts, 'FUNCAO'),
                setor: col(parts, 'SETOR'),
                responsavel: col(parts, 'RESPONSAVEL'),
                dt_admissao: parseDataBR(col(parts, 'DT_ADMISSAO')),
                dt_demissao: parseDataBR(col(parts, 'DT_DEMISSAO')),
                dt_nascimento: parseDataBR(col(parts, 'DT_NASCIMENTO')),
                cidade: col(parts, 'CIDADE'),
                estado: col(parts, 'ESTADO'),
                estabilidade: col(parts, 'ESTABILIDADE'),
                ghe: col(parts, 'GHE'),
                calca: col(parts, 'CALCA'),
                camisa: col(parts, 'CAMISA'),
                bota: col(parts, 'BOTA'),
                sexo: col(parts, 'SEXO')
            });
        }

        const efetivoArr = Array.from(efetivoMap.values());
        statusEl.textContent = `Enviando ${efetivoArr.length} colaboradores...`;
        await supabaseUpsert('colaboradores_efetivo', efetivoArr);

        statusEl.textContent = `✅ Importação concluída! ${efetivoArr.length} colaboradores importados/atualizados. ${puladas} linha(s) pulada(s) por dado incompleto.`;
        efetivoLoaded = true;
        await loadEfetivoData();
    } catch (err) {
        console.error('Erro ao importar planilha de efetivo:', err);
        statusEl.textContent = '❌ Erro na importação: ' + err.message;
    }
}

// ============================================
// ACIDENTABILIDADE (NR-01 / NBR 14280) - TF/TG usam o mesmo HHT normativo (efetivo ×
// 220h) já usado no painel Efetivo. Tabela isolada (acidentes), só lida/escrita aqui.
// ============================================

let allAcidentes = [];
let acidentesLoaded = false;
let acidentesFilter = 'mes';
let acidentesFiltroAno = '';
let acidentesFiltroMes = '';
let hhtDiasTrabalhadosMap = {}; // 'YYYY-MM' -> { dias_trabalhados, horas_por_dia }

// Ano/mês específico pra comparar períodos distantes - mesmo raciocínio do filtro
// equivalente em Treinamentos ([[popularFiltroAnoTreinamentos]]). Usa os anos já
// configurados em hht_dias_trabalhados (cobre todo o histórico do contrato) em vez de só
// os anos com acidente registrado, já que "ver 2024" deve funcionar mesmo com 0 acidentes.
function popularFiltroAnoAcidentes() {
    const anos = new Set([new Date().getFullYear()]);
    Object.values(hhtDiasTrabalhadosMap).forEach(c => anos.add(c.ano));
    allAcidentes.forEach(a => { if (a.data_acidente) anos.add(parseLocalDate(a.data_acidente).getFullYear()); });
    popularSelectAnos('acidFiltroAno', anos);
}

// HHT de Exposição real (Efetivo × Dias Trabalhados no Mês × Horas por Dia), igual à
// planilha oficial "Índices de Segurança e Saúde Ocupacional" do usuário - mais precisa
// que o hht220DoMes() (aproximação fixa) usado no painel Efetivo. Retorna null quando o
// mês TEM efetivo mas ainda não foi configurado em hhtDiasTrabalhadosMap (não dá pra
// calcular TF/TG sem esse dado, então melhor mostrar "indisponível" do que um número
// fabricado) - mas retorna 0 (não null) quando o efetivo do mês é zero (mês anterior ao
// início do contrato, por exemplo), já que aí não há exposição real a configurar e isso
// não deve travar o cálculo de um período maior que inclua esse mês.
function hhtExposicaoDoMes(ano, mesIndex0) {
    const headcount = headcountAsOf(new Date(ano, mesIndex0 + 1, 0));
    if (headcount === 0) return 0;
    const key = `${ano}-${String(mesIndex0 + 1).padStart(2, '0')}`;
    const config = hhtDiasTrabalhadosMap[key];
    if (!config || !config.dias_trabalhados) return null;
    return headcount * config.dias_trabalhados * (config.horas_por_dia || 8);
}

function getAcidentesDateRange() {
    const tituloEl = document.getElementById('acidPeriodoTitulo');
    if (acidentesFiltroAno) {
        const ano = parseInt(acidentesFiltroAno, 10);
        if (acidentesFiltroMes !== '') {
            const mes = parseInt(acidentesFiltroMes, 10);
            if (tituloEl) tituloEl.textContent = `${NOMES_MESES[mes]}/${ano}`;
            return { inicio: new Date(ano, mes, 1), fim: new Date(ano, mes + 1, 0, 23, 59, 59, 999) };
        }
        if (tituloEl) tituloEl.textContent = `Ano ${ano} (completo)`;
        return { inicio: new Date(ano, 0, 1), fim: new Date(ano, 11, 31, 23, 59, 59, 999) };
    }

    const now = new Date();
    const fim = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 23, 59, 59, 999);
    let inicio, titulo;
    if (acidentesFilter === 'trimestre') {
        inicio = new Date(now.getFullYear(), now.getMonth() - 2, 1);
        titulo = 'Últimos 3 meses';
    } else if (acidentesFilter === 'ano') {
        inicio = new Date(now.getFullYear(), 0, 1);
        titulo = `Ano ${now.getFullYear()} (até hoje)`;
    } else if (acidentesFilter === 'todos') {
        inicio = new Date(2000, 0, 1);
        titulo = 'Todo o histórico';
    } else {
        inicio = new Date(now.getFullYear(), now.getMonth(), 1);
        titulo = 'Este mês';
    }
    if (tituloEl) tituloEl.textContent = titulo;
    return { inicio, fim };
}

function setAcidentesFilter(filter) {
    acidentesFilter = filter;
    acidentesFiltroAno = '';
    acidentesFiltroMes = '';
    const anoSel = document.getElementById('acidFiltroAno'); if (anoSel) anoSel.value = '';
    const mesSel = document.getElementById('acidFiltroMes'); if (mesSel) mesSel.value = '';
    ['btnFiltroAcidMes', 'btnFiltroAcidTrimestre', 'btnFiltroAcidAno', 'btnFiltroAcidTodos'].forEach(id => {
        document.getElementById(id)?.classList.remove('active');
    });
    const map = { mes: 'btnFiltroAcidMes', trimestre: 'btnFiltroAcidTrimestre', ano: 'btnFiltroAcidAno', todos: 'btnFiltroAcidTodos' };
    document.getElementById(map[filter])?.classList.add('active');
    renderAcidentesPanel();
}

function onAcidentesFiltroAnoMesChange() {
    acidentesFiltroAno = document.getElementById('acidFiltroAno').value;
    acidentesFiltroMes = document.getElementById('acidFiltroMes').value;
    if (acidentesFiltroAno) {
        ['btnFiltroAcidMes', 'btnFiltroAcidTrimestre', 'btnFiltroAcidAno', 'btnFiltroAcidTodos'].forEach(id => {
            document.getElementById(id)?.classList.remove('active');
        });
    }
    renderAcidentesPanel();
}

async function loadAcidentesData() {
    try {
        allAcidentes = await supabaseFetch('acidentes', '?select=*');
        // Precisa do efetivo pra calcular a HHT de exposição e pra sugerir/autocompletar
        // o colaborador no formulário - carrega mesmo se o usuário nunca abriu Efetivo.
        if (allEfetivo.length === 0) {
            allEfetivo = await supabaseFetch('colaboradores_efetivo', '?select=*');
        }
        const diasTrabalhadosRows = await supabaseFetch('hht_dias_trabalhados', '?select=*');
        hhtDiasTrabalhadosMap = {};
        diasTrabalhadosRows.forEach(r => { hhtDiasTrabalhadosMap[r.id] = r; });
        popularAcidentesColabDatalist();
        renderAcidentesPanel();
    } catch (err) {
        console.error('Erro ao carregar dados de acidentes:', err);
    }
}

function popularAcidentesColabDatalist() {
    const dl = document.getElementById('acidentesColabList');
    if (!dl || dl.options.length > 0) return;
    allEfetivo.filter(colaboradorEstaAtivo).sort((a, b) => (a.nome || '').localeCompare(b.nome || '')).forEach(e => {
        const opt = document.createElement('option');
        opt.value = `${e.id} - ${e.nome}`;
        dl.appendChild(opt);
    });
}

function onAcidColaboradorChange() {
    const raw = document.getElementById('acidForm_matricula').value;
    const matricula = raw.includes(' - ') ? raw.split(' - ')[0].trim() : raw.trim();
    const colab = allEfetivo.find(e => e.id === matricula);
    if (colab && colab.setor) {
        document.getElementById('acidForm_setor').value = colab.setor;
    }
}

// Dias corridos desde o último acidente daquele tipo (com ou sem afastamento) até
// hoje - null quando não há nenhum registro desse tipo ainda (não dá pra calcular
// "dias sem" sem uma data de referência).
function diasSemAcidente(comAfastamento) {
    const hoje = new Date();
    hoje.setHours(0, 0, 0, 0);
    const relevantes = allAcidentes.filter(a => !!a.com_afastamento === comAfastamento && a.data_acidente);
    if (relevantes.length === 0) return null;
    const ultimo = relevantes.reduce((max, a) => {
        const d = parseLocalDate(a.data_acidente);
        return d > max ? d : max;
    }, new Date(0));
    ultimo.setHours(0, 0, 0, 0);
    return Math.max(0, Math.floor((hoje.getTime() - ultimo.getTime()) / (1000 * 60 * 60 * 24)));
}

function renderAcidentesPanel() {
    popularFiltroAnoAcidentes();
    const { inicio, fim } = getAcidentesDateRange();
    const periodo = allAcidentes.filter(a => {
        if (!a.data_acidente) return false;
        const d = parseLocalDate(a.data_acidente);
        return d >= inicio && d <= fim;
    });

    // HHT do período: soma a HHT de exposição real (efetivo × dias trabalhados × horas/dia)
    // de cada mês coberto. Se algum mês do período ainda não tiver dias trabalhados
    // configurados, TF/TG ficam indisponíveis (evita fabricar um número errado).
    let hhtPeriodo = 0;
    let periodoCompleto = true;
    let cursorHht = new Date(inicio.getFullYear(), inicio.getMonth(), 1);
    const limiteHht = new Date(fim.getFullYear(), fim.getMonth(), 1);
    while (cursorHht <= limiteHht) {
        const hhtMes = hhtExposicaoDoMes(cursorHht.getFullYear(), cursorHht.getMonth());
        if (hhtMes === null) periodoCompleto = false;
        else hhtPeriodo += hhtMes;
        cursorHht = new Date(cursorHht.getFullYear(), cursorHht.getMonth() + 1, 1);
    }

    const numAcidentes = periodo.length;
    const diasPerdidosTotal = periodo.reduce((s, a) => s + (parseInt(a.dias_perdidos, 10) || 0), 0);
    const diasDebitadosTotal = periodo.reduce((s, a) => s + (parseInt(a.dias_debitados, 10) || 0), 0);

    const tfDisponivel = periodoCompleto && hhtPeriodo > 0;
    const tf = tfDisponivel ? (numAcidentes * 1000000 / hhtPeriodo) : 0;
    const tg = tfDisponivel ? ((diasPerdidosTotal + diasDebitadosTotal) * 1000000 / hhtPeriodo) : 0;

    document.getElementById('kpiAcidTF').textContent = tfDisponivel ? tf.toFixed(2) : '—';
    document.getElementById('kpiAcidTG').textContent = tfDisponivel ? tg.toFixed(2) : '—';
    document.getElementById('kpiAcidTotal').textContent = numAcidentes;

    const diasCPT = diasSemAcidente(true);
    const diasSPT = diasSemAcidente(false);
    document.getElementById('kpiAcidDiasSemCPT').textContent = diasCPT === null ? '—' : diasCPT;
    document.getElementById('kpiAcidDiasSemSPT').textContent = diasSPT === null ? '—' : diasSPT;

    const listaEl = document.getElementById('listAcidentesHistorico');
    const periodoOrdenado = periodo.slice().sort((a, b) => (b.data_acidente || '').localeCompare(a.data_acidente || ''));
    if (periodoOrdenado.length === 0) {
        listaEl.innerHTML = '<div class="db-list-empty">✅ Nenhum acidente registrado no período</div>';
    } else {
        listaEl.innerHTML = periodoOrdenado.map(a => {
            const cls = a.com_afastamento ? 'db-item-danger' : 'db-item-warning';
            return `<div class="db-list-item ${cls}" style="cursor:pointer;" onclick="abrirFormAcidente('${escapeHTML(a.id)}')">
                <div class="db-list-item-title">${escapeHTML(a.tipo_acidente || 'Não especificado')} ${a.com_afastamento ? '(CPT)' : '(SPT)'}</div>
                <div class="db-list-item-sub">${escapeHTML(a.nome_colaborador || 'Não identificado')} — ${formatSimpleDate(a.data_acidente)}${a.setor ? ' — ' + escapeHTML(a.setor) : ''}</div>
            </div>`;
        }).join('');
    }

    if (typeof Chart === 'undefined') return;
    if (chartInstances.acidTFTG) chartInstances.acidTFTG.destroy();
    if (chartInstances.acidTipologia) chartInstances.acidTipologia.destroy();
    if (chartInstances.acidSetor) chartInstances.acidSetor.destroy();

    // TF/TG por mês - histórico completo desde a primeira admissão registrada (não só
    // desde o primeiro acidente - "0 acidentes" também é um dado válido pra mostrar).
    const hoje = new Date();
    const datasAdmissao = allEfetivo.filter(e => e.dt_admissao).map(e => parseLocalDate(e.dt_admissao));
    const primeiraData = datasAdmissao.length > 0 ? new Date(Math.min(...datasAdmissao.map(d => d.getTime()))) : hoje;
    const mesesAcid = [], tfPorMes = [], tgPorMes = [];
    let cursorAcid = new Date(primeiraData.getFullYear(), primeiraData.getMonth(), 1);
    const limiteAcid = new Date(hoje.getFullYear(), hoje.getMonth(), 1);
    while (cursorAcid <= limiteAcid) {
        const ano = cursorAcid.getFullYear(), mes = cursorAcid.getMonth();
        const inicioMes = new Date(ano, mes, 1);
        const fimMes = new Date(ano, mes + 1, 0);
        mesesAcid.push(cursorAcid.toLocaleDateString('pt-BR', { month: 'short', year: '2-digit' }));
        const acidDoMes = allAcidentes.filter(a => a.data_acidente && parseLocalDate(a.data_acidente) >= inicioMes && parseLocalDate(a.data_acidente) <= fimMes);
        const hhtMes = hhtExposicaoDoMes(ano, mes);
        const dPerdidosMes = acidDoMes.reduce((s, a) => s + (parseInt(a.dias_perdidos, 10) || 0), 0);
        const dDebitadosMes = acidDoMes.reduce((s, a) => s + (parseInt(a.dias_debitados, 10) || 0), 0);
        // hhtMes null = mês sem "dias trabalhados" configurado - plota como gap (null),
        // não como 0, pra não sugerir visualmente "TF/TG medido igual a zero".
        tfPorMes.push(hhtMes ? Math.round((acidDoMes.length * 1000000 / hhtMes) * 100) / 100 : null);
        tgPorMes.push(hhtMes ? Math.round(((dPerdidosMes + dDebitadosMes) * 1000000 / hhtMes) * 100) / 100 : null);
        cursorAcid = new Date(ano, mes + 1, 1);
    }

    chartInstances.acidTFTG = new Chart(document.getElementById('chartAcidTFTG'), {
        type: 'line',
        data: {
            labels: mesesAcid,
            datasets: [
                { label: 'TF', data: tfPorMes, borderColor: '#4f46e5', backgroundColor: 'rgba(79,70,229,0.08)', fill: true, tension: 0.25, yAxisID: 'y' },
                { label: 'TG', data: tgPorMes, borderColor: '#ef4444', backgroundColor: 'transparent', tension: 0.25, yAxisID: 'y1' }
            ]
        },
        options: {
            responsive: true, maintainAspectRatio: false,
            scales: {
                y: { position: 'left', beginAtZero: true, title: { display: true, text: 'TF' } },
                y1: { position: 'right', beginAtZero: true, grid: { drawOnChartArea: false }, title: { display: true, text: 'TG' } }
            }
        }
    });

    const tipoCounts = {};
    allAcidentes.forEach(a => { const t = a.tipo_acidente || 'Não especificado'; tipoCounts[t] = (tipoCounts[t] || 0) + 1; });
    const tipoSorted = Object.entries(tipoCounts).sort((a, b) => b[1] - a[1]);
    const tipoLabels = tipoSorted.map(t => wrapChartLabel(t[0]));
    ajustarAlturaBarrasHorizontais('chartAcidTipologia', tipoLabels);
    chartInstances.acidTipologia = new Chart(document.getElementById('chartAcidTipologia'), {
        type: 'bar',
        data: { labels: tipoLabels, datasets: [{ label: 'Acidentes', data: tipoSorted.map(t => t[1]), backgroundColor: '#f59e0b', borderRadius: 6 }] },
        options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { beginAtZero: true, ticks: { stepSize: 1 } }, y: { ticks: { autoSkip: false } } } }
    });

    const setorCounts = {};
    allAcidentes.forEach(a => { const s = a.setor || 'Não informado'; setorCounts[s] = (setorCounts[s] || 0) + 1; });
    const setorSorted = Object.entries(setorCounts).sort((a, b) => b[1] - a[1]);
    const setorLabels = setorSorted.map(s => wrapChartLabel(s[0]));
    ajustarAlturaBarrasHorizontais('chartAcidSetor', setorLabels);
    chartInstances.acidSetor = new Chart(document.getElementById('chartAcidSetor'), {
        type: 'bar',
        data: { labels: setorLabels, datasets: [{ label: 'Acidentes', data: setorSorted.map(s => s[1]), backgroundColor: '#ef4444', borderRadius: 6 }] },
        options: { responsive: true, maintainAspectRatio: false, indexAxis: 'y', plugins: { legend: { display: false } }, scales: { x: { beginAtZero: true, ticks: { stepSize: 1 } }, y: { ticks: { autoSkip: false } } } }
    });
}

function abrirFormAcidente(id) {
    const form = document.getElementById('acidenteFormCard');
    const title = document.getElementById('acidenteFormTitle');
    const btnExcluir = document.getElementById('acidForm_btnExcluir');
    document.getElementById('acidenteFormStatus').textContent = '';
    popularAcidentesColabDatalist();

    if (id) {
        const a = allAcidentes.find(x => x.id === id);
        if (!a) return;
        title.textContent = '✏️ Editar Acidente';
        form.dataset.editId = id;
        document.getElementById('acidForm_data').value = a.data_acidente || '';
        document.getElementById('acidForm_matricula').value = a.matricula ? `${a.matricula} - ${a.nome_colaborador || ''}` : (a.nome_colaborador || '');
        document.getElementById('acidForm_setor').value = a.setor || '';
        document.getElementById('acidForm_tipo').value = a.tipo_acidente || '';
        document.getElementById('acidForm_afastamento').value = a.com_afastamento ? 'sim' : 'nao';
        document.getElementById('acidForm_diasPerdidos').value = a.dias_perdidos || 0;
        document.getElementById('acidForm_diasDebitados').value = a.dias_debitados || 0;
        document.getElementById('acidForm_parteCorpo').value = a.parte_corpo || '';
        document.getElementById('acidForm_agenteCausador').value = a.agente_causador || '';
        document.getElementById('acidForm_local').value = a.local || '';
        document.getElementById('acidForm_descricao').value = a.descricao || '';
        btnExcluir.style.display = 'inline-block';
    } else {
        title.textContent = '🚑 Registrar Acidente';
        delete form.dataset.editId;
        document.getElementById('acidForm_data').value = new Date().toISOString().split('T')[0];
        document.getElementById('acidForm_matricula').value = '';
        document.getElementById('acidForm_setor').value = '';
        document.getElementById('acidForm_tipo').value = '';
        document.getElementById('acidForm_afastamento').value = 'nao';
        document.getElementById('acidForm_diasPerdidos').value = 0;
        document.getElementById('acidForm_diasDebitados').value = 0;
        document.getElementById('acidForm_parteCorpo').value = '';
        document.getElementById('acidForm_agenteCausador').value = '';
        document.getElementById('acidForm_local').value = '';
        document.getElementById('acidForm_descricao').value = '';
        btnExcluir.style.display = 'none';
    }

    showAcidentesSubtab('registrar');
}

function fecharFormAcidente() {
    showAcidentesSubtab('visao');
}

async function salvarAcidente() {
    const statusEl = document.getElementById('acidenteFormStatus');
    const data = document.getElementById('acidForm_data').value;
    const tipo = document.getElementById('acidForm_tipo').value;

    if (!data || !tipo) {
        statusEl.textContent = '❌ Data e tipo de acidente são obrigatórios.';
        statusEl.style.color = 'var(--danger)';
        return;
    }

    const rawColab = document.getElementById('acidForm_matricula').value.trim();
    let matricula = '', nomeColaborador = '', funcao = '';
    if (rawColab) {
        matricula = rawColab.includes(' - ') ? rawColab.split(' - ')[0].trim() : rawColab;
        const colab = allEfetivo.find(e => e.id === matricula);
        if (colab) {
            nomeColaborador = colab.nome || '';
            funcao = colab.funcao || '';
        } else {
            // Não bateu com nenhuma matrícula cadastrada - trata como nome livre
            // (terceiro/visitante sem cadastro no efetivo).
            nomeColaborador = rawColab;
            matricula = '';
        }
    }

    const form = document.getElementById('acidenteFormCard');
    const editId = form.dataset.editId;
    const id = editId || ('ACID_' + Date.now());

    const row = {
        id,
        data_acidente: data,
        matricula: matricula || null,
        nome_colaborador: nomeColaborador || null,
        funcao: funcao || null,
        setor: document.getElementById('acidForm_setor').value.trim() || null,
        tipo_acidente: tipo,
        com_afastamento: document.getElementById('acidForm_afastamento').value === 'sim',
        dias_perdidos: parseInt(document.getElementById('acidForm_diasPerdidos').value, 10) || 0,
        dias_debitados: parseInt(document.getElementById('acidForm_diasDebitados').value, 10) || 0,
        parte_corpo: document.getElementById('acidForm_parteCorpo').value.trim() || null,
        agente_causador: document.getElementById('acidForm_agenteCausador').value.trim() || null,
        local: document.getElementById('acidForm_local').value.trim() || null,
        descricao: document.getElementById('acidForm_descricao').value.trim() || null
    };

    statusEl.textContent = 'Salvando...';
    statusEl.style.color = 'var(--text-light)';
    try {
        await supabaseUpsert('acidentes', [row]);
        const idx = allAcidentes.findIndex(a => a.id === id);
        if (idx >= 0) allAcidentes[idx] = { ...allAcidentes[idx], ...row };
        else allAcidentes.push(row);

        statusEl.textContent = '✅ Salvo com sucesso.';
        statusEl.style.color = 'var(--success)';
        setTimeout(() => fecharFormAcidente(), 900);
    } catch (err) {
        console.error('Erro ao salvar acidente:', err);
        statusEl.textContent = '❌ Falha ao salvar: ' + err.message;
        statusEl.style.color = 'var(--danger)';
    }
}

async function excluirAcidenteAtual() {
    const form = document.getElementById('acidenteFormCard');
    const id = form.dataset.editId;
    if (!id) return;
    if (!confirm('Excluir este registro de acidente? Essa ação não pode ser desfeita.')) return;

    const statusEl = document.getElementById('acidenteFormStatus');
    statusEl.textContent = 'Excluindo...';
    statusEl.style.color = 'var(--text-light)';
    try {
        await supabaseDelete('acidentes', id);
        allAcidentes = allAcidentes.filter(a => a.id !== id);
        statusEl.textContent = '✅ Excluído com sucesso.';
        statusEl.style.color = 'var(--success)';
        setTimeout(() => fecharFormAcidente(), 900);
    } catch (err) {
        console.error('Erro ao excluir acidente:', err);
        statusEl.textContent = '❌ Falha ao excluir: ' + err.message;
        statusEl.style.color = 'var(--danger)';
    }
}

// ============================================
// SAÚDE OCUPACIONAL (NR-07 / PCMSO) - Controle de ASO (vencido/vencendo/em dia/sem
// registro, calculado a partir do exame mais recente de cada colaborador ativo) e Taxa
// de Absenteísmo Ocupacional (horas perdidas por atestado de doença ocupacional OU
// acidente de trabalho, sobre a mesma HHT de exposição já usada em Acidentabilidade).
// ============================================

let allAsoExames = [];
let allAtestadosOcupacionais = [];
let saudeLoaded = false;
let saudeFilter = 'mes';
let saudeFiltroAno = '';
let saudeFiltroMes = '';

const ASO_TIPO_LABELS = {
    admissional: 'Admissional',
    periodico: 'Periódico',
    demissional: 'Demissional',
    retorno_trabalho: 'Retorno ao Trabalho',
    mudanca_risco: 'Mudança de Risco'
};

function popularFiltroAnoSaude() {
    const anos = new Set([new Date().getFullYear()]);
    Object.values(hhtDiasTrabalhadosMap).forEach(c => anos.add(c.ano));
    allAsoExames.forEach(a => { if (a.data_exame) anos.add(parseLocalDate(a.data_exame).getFullYear()); });
    popularSelectAnos('saudeFiltroAno', anos);
}

function getSaudeDateRange() {
    const tituloEl = document.getElementById('saudePeriodoTitulo');
    if (saudeFiltroAno) {
        const ano = parseInt(saudeFiltroAno, 10);
        if (saudeFiltroMes !== '') {
            const mes = parseInt(saudeFiltroMes, 10);
            if (tituloEl) tituloEl.textContent = `${NOMES_MESES[mes]}/${ano}`;
            return { inicio: new Date(ano, mes, 1), fim: new Date(ano, mes + 1, 0, 23, 59, 59, 999) };
        }
        if (tituloEl) tituloEl.textContent = `Ano ${ano} (completo)`;
        return { inicio: new Date(ano, 0, 1), fim: new Date(ano, 11, 31, 23, 59, 59, 999) };
    }

    const now = new Date();
    const fim = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 1, 23, 59, 59, 999);
    let inicio, titulo;
    if (saudeFilter === 'trimestre') {
        inicio = new Date(now.getFullYear(), now.getMonth() - 2, 1);
        titulo = 'Últimos 3 meses';
    } else if (saudeFilter === 'ano') {
        inicio = new Date(now.getFullYear(), 0, 1);
        titulo = `Ano ${now.getFullYear()} (até hoje)`;
    } else if (saudeFilter === 'todos') {
        inicio = new Date(2000, 0, 1);
        titulo = 'Todo o histórico';
    } else {
        inicio = new Date(now.getFullYear(), now.getMonth(), 1);
        titulo = 'Este mês';
    }
    if (tituloEl) tituloEl.textContent = titulo;
    return { inicio, fim };
}

function setSaudeFilter(filter) {
    saudeFilter = filter;
    saudeFiltroAno = '';
    saudeFiltroMes = '';
    const anoSel = document.getElementById('saudeFiltroAno'); if (anoSel) anoSel.value = '';
    const mesSel = document.getElementById('saudeFiltroMes'); if (mesSel) mesSel.value = '';
    ['btnFiltroSaudeMes', 'btnFiltroSaudeTrimestre', 'btnFiltroSaudeAno', 'btnFiltroSaudeTodos'].forEach(id => {
        document.getElementById(id)?.classList.remove('active');
    });
    const map = { mes: 'btnFiltroSaudeMes', trimestre: 'btnFiltroSaudeTrimestre', ano: 'btnFiltroSaudeAno', todos: 'btnFiltroSaudeTodos' };
    document.getElementById(map[filter])?.classList.add('active');
    renderSaudePanel();
}

function onSaudeFiltroAnoMesChange() {
    saudeFiltroAno = document.getElementById('saudeFiltroAno').value;
    saudeFiltroMes = document.getElementById('saudeFiltroMes').value;
    if (saudeFiltroAno) {
        ['btnFiltroSaudeMes', 'btnFiltroSaudeTrimestre', 'btnFiltroSaudeAno', 'btnFiltroSaudeTodos'].forEach(id => {
            document.getElementById(id)?.classList.remove('active');
        });
    }
    renderSaudePanel();
}

async function loadSaudeData() {
    try {
        const [asoRows, atestadoRows] = await Promise.all([
            supabaseFetch('aso_exames', '?select=*'),
            supabaseFetch('atestados_ocupacionais', '?select=*')
        ]);
        allAsoExames = asoRows;
        allAtestadosOcupacionais = atestadoRows;
        // Precisa do efetivo (quem está ativo hoje), da configuração de dias trabalhados
        // (denominador da HHT) e dos acidentes (dias perdidos por acidente também contam
        // no absenteísmo ocupacional) - carrega tudo que ainda não tiver sido carregado.
        if (allEfetivo.length === 0) allEfetivo = await supabaseFetch('colaboradores_efetivo', '?select=*');
        if (Object.keys(hhtDiasTrabalhadosMap).length === 0) {
            const diasTrabalhadosRows = await supabaseFetch('hht_dias_trabalhados', '?select=*');
            diasTrabalhadosRows.forEach(r => { hhtDiasTrabalhadosMap[r.id] = r; });
        }
        if (allAcidentes.length === 0) allAcidentes = await supabaseFetch('acidentes', '?select=*');
        popularSaudeColabDatalists();
        renderSaudePanel();
    } catch (err) {
        console.error('Erro ao carregar dados de saúde ocupacional:', err);
    }
}

function popularSaudeColabDatalists() {
    ['asoColabList', 'atestadoColabList'].forEach(dlId => {
        const dl = document.getElementById(dlId);
        if (!dl || dl.options.length > 0) return;
        allEfetivo.filter(colaboradorEstaAtivo).sort((a, b) => (a.nome || '').localeCompare(b.nome || '')).forEach(e => {
            const opt = document.createElement('option');
            opt.value = `${e.id} - ${e.nome}`;
            dl.appendChild(opt);
        });
    });
}

function buscarColaboradorPorInput(inputId) {
    const raw = document.getElementById(inputId).value;
    const matricula = raw.includes(' - ') ? raw.split(' - ')[0].trim() : raw.trim();
    return { matricula, colab: allEfetivo.find(e => e.id === matricula) };
}

