    razaoSocial: 'CONSORCIO OPERADOR RAMAL DO AGRESTE',
    cnpj: '55.623.017/0001-97',
    cnaePrincipal: '71.12-0-00 - Serviços de engenharia',
    naturezaJuridica: '215-1 - Consórcio de Sociedades',
